insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c5000000-0000-0000-0000-000000000001', 'ukmla', 'c9d9be7a-b343-4be3-8527-cdfde9cb2800',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c5000000-0000-0000-0000-000000000001', 'A', 'Immediate IV hydrocortisone 100 mg bolus and rapid IV 0.9% sodium chloride, with continued IV hydrocortisone and glucose monitoring', true, 'Correct. This is an Addisonian (adrenal) crisis: shock, hyponatraemia, hyperkalaemia and hypoglycaemia in a patient unable to absorb oral steroid during intercurrent illness. Immediate IV hydrocortisone and aggressive IV fluid resuscitation are life-saving and should not be delayed for confirmatory tests.', 1),
('c5000000-0000-0000-0000-000000000001', 'B', 'Double her oral hydrocortisone dose and observe on the ward', false, 'Ruled out because she is shocked and vomiting, so oral absorption cannot be relied upon; a crisis of this severity requires parenteral steroid and IV fluids, not an increased oral dose.', 2),
('c5000000-0000-0000-0000-000000000001', 'C', 'Withhold steroids until a short synacthen test confirms the diagnosis', false, 'Ruled out because this is a clinical emergency; waiting for confirmatory endocrine testing before treating risks cardiovascular collapse and death. Treatment is started empirically on clinical suspicion.', 3),
('c5000000-0000-0000-0000-000000000001', 'D', 'Give IV insulin and dextrose to correct the hyperkalaemia as the first priority', false, 'Ruled out because the hyperkalaemia here is secondary to cortisol deficiency and will correct with hydrocortisone and fluid resuscitation; insulin/dextrose is not the primary treatment and risks worsening her hypoglycaemia.', 4),
('c5000000-0000-0000-0000-000000000001', 'E', 'Administer intramuscular glucagon for the hypoglycaemia and reassess in one hour', false, 'Ruled out because glucagon does not address the underlying cortisol deficiency or haemodynamic collapse; this is an adrenal crisis requiring immediate steroid replacement and fluids.', 5),
('c5000000-0000-0000-0000-000000000002', 'A', '24-hour urinary free cortisol', false, $x$Ruled out because this test is used to diagnose cortisol excess (Cushing's syndrome), not to diagnose or characterise adrenal insufficiency.$x$, 1),
('c5000000-0000-0000-0000-000000000002', 'B', 'Short synacthen (ACTH stimulation) test with paired plasma ACTH', true, $x$Correct. Failure of cortisol to rise after synthetic ACTH confirms adrenal insufficiency; a markedly raised plasma ACTH indicates primary adrenal failure (Addison's disease, explaining the hyperpigmentation from excess ACTH/POMC), whereas a low or inappropriately normal ACTH indicates secondary (pituitary) causes.$x$, 2),
('c5000000-0000-0000-0000-000000000002', 'C', 'Overnight dexamethasone suppression test', false, $x$Ruled out because this test screens for Cushing's syndrome (cortisol excess); it has no role in confirming adrenal insufficiency.$x$, 3),
('c5000000-0000-0000-0000-000000000002', 'D', 'Renin:aldosterone ratio', false, $x$Ruled out because this is used to investigate suspected primary hyperaldosteronism (Conn's syndrome), which presents with hypertension and hypokalaemia, the opposite biochemical picture to this patient.$x$, 4),
('c5000000-0000-0000-0000-000000000002', 'E', 'Water deprivation test', false, $x$Ruled out because this test is used to investigate suspected diabetes insipidus (polyuria/polydipsia), which is not this patient's presentation.$x$, 5),
('c5000000-0000-0000-0000-000000000003', 'A', 'Continue his usual hydrocortisone dose unchanged, as illness does not affect steroid requirements', false, 'Ruled out because physiological stress from infection increases cortisol requirements; failing to increase the dose risks precipitating an adrenal crisis.', 1),
('c5000000-0000-0000-0000-000000000003', 'B', 'Stop his hydrocortisone until the infection resolves to avoid immunosuppression', false, 'Ruled out because abruptly stopping glucocorticoid replacement in adrenal insufficiency is dangerous and can precipitate a life-threatening adrenal crisis.', 2),
('c5000000-0000-0000-0000-000000000003', 'C', 'Halve his hydrocortisone dose to reduce infection risk', false, 'Ruled out because reducing steroid replacement during illness increases the risk of adrenal crisis; the correct action is to increase, not decrease, the dose.', 3),
('c5000000-0000-0000-0000-000000000003', 'D', 'Double his usual oral hydrocortisone dose for the duration of the illness and seek medical attention if he cannot keep tablets down or deteriorates', true, $x$Correct. 'Sick day rules' for steroid-dependent patients require doubling the usual glucocorticoid replacement dose during intercurrent febrile illness, with clear advice to seek urgent medical review (for parenteral hydrocortisone) if vomiting, diarrhoea, or worsening illness prevents adequate oral intake, to prevent progression to an adrenal crisis.$x$, 4),
('c5000000-0000-0000-0000-000000000003', 'E', 'Switch him from hydrocortisone to prednisolone for the duration of the illness', false, 'Ruled out because switching glucocorticoid preparation is unnecessary and does not address the need for an increased replacement dose during illness.', 5),
('c5000000-0000-0000-0000-000000000004', 'A', 'He can stop immediately since his underlying rheumatoid arthritis is now controlled', false, 'Ruled out because stopping long-term steroids abruptly risks adrenal crisis from HPA axis suppression, regardless of how well the underlying disease is controlled.', 1),
('c5000000-0000-0000-0000-000000000004', 'B', 'He should increase the dose further to treat the new hypertension and hyperglycaemia', false, 'Ruled out because increasing the steroid dose would worsen, not treat, his iatrogenic Cushingoid features, hypertension and hyperglycaemia.', 2),
('c5000000-0000-0000-0000-000000000004', 'C', 'The prednisolone must be tapered gradually rather than stopped abruptly, because long-term use has suppressed his own adrenal (HPA) axis', true, $x$Correct. His clinical picture (central obesity, moon face, striae/bruising, hypertension, hyperglycaemia) is iatrogenic Cushing's syndrome from prolonged exogenous steroid use. Prolonged glucocorticoid therapy suppresses the hypothalamic-pituitary-adrenal axis; abrupt cessation can precipitate an adrenal crisis because the adrenal glands cannot immediately resume adequate cortisol production. The dose must be weaned slowly to allow HPA axis recovery.$x$, 3),
('c5000000-0000-0000-0000-000000000004', 'D', 'He should switch to an equivalent dose of hydrocortisone and stop that abruptly instead', false, 'Ruled out because switching glucocorticoid preparation does not address HPA axis suppression; any withdrawal after prolonged therapy must still be a gradual taper.', 4),
('c5000000-0000-0000-0000-000000000004', 'E', 'No action is needed as the Cushingoid features will resolve on their own regardless of how the drug is stopped', false, 'Ruled out because features may persist and, more importantly, stopping abruptly risks a life-threatening adrenal crisis due to a suppressed HPA axis.', 5),
('c5000000-0000-0000-0000-000000000005', 'A', 'Phaeochromocytoma', false, 'Ruled out because phaeochromocytoma typically causes episodic headache, palpitations, sweating and paroxysmal hypertension due to catecholamine excess, not the hypokalaemia/suppressed renin pattern seen here.', 1),
('c5000000-0000-0000-0000-000000000005', 'B', $x$Cushing's syndrome$x$, false, $x$Ruled out because although Cushing's syndrome can cause hypertension and hypokalaemia at very high cortisol levels, the renin-aldosterone axis pattern described (suppressed renin, raised aldosterone) is specific to primary hyperaldosteronism.$x$, 2),
('c5000000-0000-0000-0000-000000000005', 'C', 'Renal artery stenosis', false, 'Ruled out because renal artery stenosis causes secondary hyperaldosteronism with raised renin (activated renin-angiotensin system), not the suppressed renin seen in this patient.', 3),
('c5000000-0000-0000-0000-000000000005', 'D', 'Congenital adrenal hyperplasia', false, 'Ruled out because this is a condition typically presenting in infancy/childhood with ambiguous genitalia or salt-wasting crises, not new resistant hypertension in a 52-year-old.', 4),
('c5000000-0000-0000-0000-000000000005', 'E', $x$Primary hyperaldosteronism (Conn's syndrome)$x$, true, 'Correct. Resistant hypertension with unprovoked hypokalaemia, metabolic alkalosis, suppressed renin and raised aldosterone (high aldosterone:renin ratio) is classic for primary hyperaldosteronism, due to an aldosterone-producing adrenal adenoma or bilateral adrenal hyperplasia.', 5),
('c5000000-0000-0000-0000-000000000006', 'A', 'Start a beta-blocker alone to control the palpitations and blood pressure before surgery', false, 'Ruled out because giving a beta-blocker before adequate alpha-blockade leaves alpha-adrenergic vasoconstriction unopposed, which can cause a severe, potentially fatal hypertensive crisis.', 1),
('c5000000-0000-0000-0000-000000000006', 'B', 'No specific preoperative medical preparation is required if blood pressure is normal between episodes', false, 'Ruled out because intraoperative manipulation of a phaeochromocytoma can trigger a massive catecholamine surge and hypertensive crisis regardless of baseline blood pressure; alpha-blockade preparation is mandatory.', 2),
('c5000000-0000-0000-0000-000000000006', 'C', 'Adequate alpha-adrenergic blockade (e.g. with phenoxybenzamine) for at least 1-2 weeks before surgery, with beta-blockade added only after alpha-blockade is established', true, 'Correct. Phaeochromocytomas secrete catecholamines that cause severe hypertensive surges; alpha-blockade must be established first to control blood pressure and allow volume expansion. Adding a beta-blocker before adequate alpha-blockade is dangerous, as unopposed alpha-adrenergic vasoconstriction (from blocking the compensatory beta-2 vasodilation) can precipitate a hypertensive crisis.', 3),
('c5000000-0000-0000-0000-000000000006', 'D', 'Give a loop diuretic to reduce circulating volume before surgery', false, 'Ruled out because phaeochromocytoma patients are typically volume-depleted from chronic vasoconstriction; the correct preparation involves volume expansion alongside alpha-blockade, not diuresis.', 4),
('c5000000-0000-0000-0000-000000000006', 'E', 'Proceed directly to surgery, as delaying resection risks malignant transformation', false, 'Ruled out because adequate preoperative alpha-blockade takes precedence over speed; operating on an unprepared patient risks life-threatening intraoperative catecholamine crisis.', 5),
('c5000000-0000-0000-0000-000000000007', 'A', 'Primary adrenal insufficiency due to autoimmune destruction of the adrenal cortex', false, $x$Ruled out because primary adrenal insufficiency (Addison's disease) is characterised by a raised, not low, plasma ACTH, as the pituitary responds to low cortisol by increasing ACTH secretion.$x$, 1),
('c5000000-0000-0000-0000-000000000007', 'B', 'Secondary adrenal insufficiency due to HPA axis suppression from long-term exogenous corticosteroid use', true, 'Correct. Chronic exogenous glucocorticoid therapy suppresses hypothalamic CRH and pituitary ACTH secretion through negative feedback, leading to adrenal atrophy. This produces secondary adrenal insufficiency with a low ACTH (rather than the raised ACTH seen in primary adrenal failure), and she is unable to mount an adequate cortisol response during acute illness.', 2),
('c5000000-0000-0000-0000-000000000007', 'C', 'Adrenal haemorrhage secondary to sepsis (Waterhouse-Friderichsen syndrome)', false, 'Ruled out because although this can cause acute primary adrenal insufficiency in severe sepsis (classically meningococcal), it would also present with a raised, not low, ACTH, and there is no history here suggesting this specific complication.', 3),
('c5000000-0000-0000-0000-000000000007', 'D', 'Tuberculous destruction of the adrenal glands', false, 'Ruled out because this is a cause of primary adrenal insufficiency, which would present with raised, not suppressed, ACTH.', 4),
('c5000000-0000-0000-0000-000000000007', 'E', 'Congenital adrenal hyperplasia presenting for the first time in adulthood', false, 'Ruled out because this is a genetic enzyme deficiency presenting typically in infancy or childhood, not a plausible new diagnosis in a 61-year-old on long-term steroids.', 5),
('c5000000-0000-0000-0000-000000000008', 'A', 'Primary hyperparathyroidism', true, 'Correct. Raised calcium with an inappropriately raised (rather than suppressed) PTH, low phosphate, and a history of renal stones is the classic biochemical and clinical picture of primary hyperparathyroidism, usually due to a solitary parathyroid adenoma.', 1),
('c5000000-0000-0000-0000-000000000008', 'B', 'Hypercalcaemia of malignancy', false, 'Ruled out because malignancy-associated hypercalcaemia (e.g. via PTH-related peptide) causes a suppressed, not raised, PTH level due to negative feedback.', 2),
('c5000000-0000-0000-0000-000000000008', 'C', 'Vitamin D toxicity', false, $x$Ruled out because vitamin D excess causes hypercalcaemia with a suppressed PTH and typically raised phosphate, the opposite pattern to this patient's raised PTH and low phosphate.$x$, 3),
('c5000000-0000-0000-0000-000000000008', 'D', 'Sarcoidosis', false, 'Ruled out because granulomatous disease causes hypercalcaemia through excess extra-renal vitamin D activation, which suppresses PTH, unlike the raised PTH seen here.', 4),
('c5000000-0000-0000-0000-000000000008', 'E', 'Secondary hyperparathyroidism due to chronic kidney disease', false, 'Ruled out because secondary hyperparathyroidism occurs in the context of low or normal calcium (driven by phosphate retention and low vitamin D in CKD), not the frank hypercalcaemia seen in this patient.', 5),
('c5000000-0000-0000-0000-000000000009', 'A', 'Reassurance only, as a T-score above -3.0 does not require treatment', false, 'Ruled out because a T-score of -2.5 or below defines osteoporosis, and combined with a fragility fracture this patient requires active treatment, not reassurance alone.', 1),
('c5000000-0000-0000-0000-000000000009', 'B', 'Calcium and vitamin D supplementation alone, without a bone-protective drug', false, 'Ruled out because supplementation alone is inadequate for a patient with confirmed osteoporosis and a fragility fracture; a bone-protective agent such as a bisphosphonate is required.', 2),
('c5000000-0000-0000-0000-000000000009', 'C', 'Hormone replacement therapy as first-line treatment for postmenopausal osteoporosis', false, 'Ruled out because HRT is not first-line for osteoporosis treatment in this age group due to its risk profile; bisphosphonates are preferred first-line agents.', 3),
('c5000000-0000-0000-0000-000000000009', 'D', 'Referral for urgent surgical fixation of the fracture only, with no further bone health assessment needed', false, 'Ruled out because although the acute fracture needs appropriate orthopaedic management, failing to address the underlying osteoporosis leaves her at high risk of further fragility fractures.', 4),
('c5000000-0000-0000-0000-000000000009', 'E', 'Oral alendronic acid, alongside calcium and vitamin D supplementation if dietary intake is insufficient', true, 'Correct. A T-score of -2.7 with a fragility fracture confirms osteoporosis. Oral bisphosphonates (e.g. alendronic acid) are first-line treatment, alongside ensuring adequate calcium and vitamin D intake, to reduce future fracture risk.', 5),
('c5000000-0000-0000-0000-000000000010', 'A', 'Osteoporosis', false, 'Ruled out because osteoporosis is a disorder of reduced bone density with normal mineralisation and normal biochemistry (calcium, phosphate, ALP); it does not cause proximal myopathy or biochemical derangement.', 1),
('c5000000-0000-0000-0000-000000000010', 'B', 'Primary hyperparathyroidism', false, 'Ruled out because this typically causes hypercalcaemia with low phosphate and raised PTH, not the low-normal calcium seen in this patient; the clinical picture and risk factors here point to vitamin D deficiency instead.', 2),
('c5000000-0000-0000-0000-000000000010', 'C', $x$Paget's disease of bone$x$, false, $x$Ruled out because Paget's disease typically presents with localised bone pain/deformity and an isolated raised ALP with normal calcium and phosphate, rather than diffuse pain with proximal myopathy and vitamin D deficiency.$x$, 3),
('c5000000-0000-0000-0000-000000000010', 'D', 'Osteomalacia due to vitamin D deficiency', true, 'Correct. Diffuse bone pain, proximal myopathy, low/low-normal calcium and phosphate, raised ALP, and severe vitamin D deficiency in a patient with reduced sun exposure and dietary risk factors is characteristic of osteomalacia (the adult equivalent of rickets), caused by impaired bone mineralisation from vitamin D deficiency.', 4),
('c5000000-0000-0000-0000-000000000010', 'E', 'Multiple myeloma', false, 'Ruled out because myeloma classically causes hypercalcaemia, renal impairment, anaemia and bone lesions, not the low-normal calcium and phosphate with markedly low vitamin D seen here.', 5),
('c5000000-0000-0000-0000-000000000011', 'A', 'Oral fluids and observation, as calcium levels will self-correct once he stops vomiting', false, 'Ruled out because calcium of 3.6 mmol/L with confusion is severe and requires urgent IV treatment, not observation, given the risk of arrhythmia and worsening consciousness.', 1),
('c5000000-0000-0000-0000-000000000011', 'B', 'Aggressive IV 0.9% sodium chloride rehydration followed by IV bisphosphonate (e.g. zoledronic acid) once rehydrated', true, 'Correct. Severe symptomatic hypercalcaemia (>3.5 mmol/L) in malignancy is a medical emergency. Initial management is vigorous IV fluid rehydration to correct dehydration and promote renal calcium excretion, followed by an IV bisphosphonate to inhibit osteoclastic bone resorption, which is the mainstay of definitive treatment for malignancy-associated hypercalcaemia.', 2),
('c5000000-0000-0000-0000-000000000011', 'C', 'Loop diuretic (furosemide) as first-line treatment to promote calcium excretion', false, 'Ruled out because loop diuretics can worsen dehydration and are not first-line; they may even increase calcium in a volume-depleted patient. Rehydration with IV saline comes first.', 3),
('c5000000-0000-0000-0000-000000000011', 'D', 'Oral calcium-lowering bisphosphonate started immediately, without prior rehydration', false, 'Ruled out because rehydration with IV fluids must occur first to correct dehydration and avoid worsening renal function; IV (not oral) bisphosphonate is then used once rehydrated.', 4),
('c5000000-0000-0000-0000-000000000011', 'E', 'Subcutaneous calcitonin as monotherapy with no other intervention', false, 'Ruled out because although calcitonin can provide a rapid but short-lived reduction in severe cases, it is not used as sole therapy; IV fluids and bisphosphonate are the mainstay treatment.', 5),
('c5000000-0000-0000-0000-000000000012', 'A', 'Reassurance, as these signs are a normal postoperative finding after thyroidectomy', false, $x$Ruled out because Chvostek's and Trousseau's signs indicate significant neuromuscular irritability from hypocalcaemia, a recognised and potentially serious complication that requires urgent assessment and treatment, not reassurance.$x$, 1),
('c5000000-0000-0000-0000-000000000012', 'B', 'Urgent CT neck to look for a postoperative haematoma', false, $x$Ruled out because her symptoms (perioral tingling, positive Chvostek's/Trousseau's signs) are classic for hypocalcaemia, not haematoma, which would more typically present with airway compromise/neck swelling; the priority is calcium measurement and treatment.$x$, 2),
('c5000000-0000-0000-0000-000000000012', 'C', 'Oral calcium supplementation only, with no other action needed', false, 'Ruled out because with symptomatic hypocalcaemia and positive tetany signs, IV calcium replacement is needed for prompt correction; oral supplementation alone is insufficient acutely.', 3),
('c5000000-0000-0000-0000-000000000012', 'D', 'Start levothyroxine immediately to treat postoperative hypothyroidism', false, 'Ruled out because her acute symptoms are due to hypocalcaemia from parathyroid disruption, not thyroid hormone deficiency; levothyroxine replacement is a separate, non-urgent consideration after thyroidectomy.', 4),
('c5000000-0000-0000-0000-000000000012', 'E', 'Urgent serum calcium measurement and IV calcium gluconate if hypocalcaemia is confirmed', true, $x$Correct. Chvostek's sign (facial twitching on tapping the facial nerve) and Trousseau's sign (carpal spasm with cuff inflation) indicate neuromuscular irritability from hypocalcaemia, a recognised complication of thyroidectomy due to inadvertent parathyroid gland disruption/devascularisation. Urgent calcium level confirmation and IV calcium gluconate replacement for symptomatic hypocalcaemia is required to prevent progression to seizures or laryngospasm.$x$, 5),
('c5000000-0000-0000-0000-000000000013', 'A', $x$Paget's disease of bone$x$, true, $x$Correct. An isolated raised ALP with normal calcium and phosphate, localised bone pain, and characteristic X-ray changes (cortical thickening, bone deformity, mixed lytic/sclerotic appearance) are classic for Paget's disease, a disorder of excessive, disorganised bone remodelling.$x$, 1),
('c5000000-0000-0000-0000-000000000013', 'B', 'Osteomalacia', false, 'Ruled out because osteomalacia typically causes low/low-normal calcium and phosphate alongside a raised ALP, not the isolated ALP rise with normal calcium/phosphate seen in this patient.', 2),
('c5000000-0000-0000-0000-000000000013', 'C', 'Bone metastases from an occult malignancy', false, $x$Ruled out because although metastases can raise ALP, the specific localised X-ray appearance (cortical thickening, bowing) and isolated biochemical pattern here are classic for Paget's disease rather than metastatic disease.$x$, 3),
('c5000000-0000-0000-0000-000000000013', 'D', 'Primary hyperparathyroidism', false, 'Ruled out because this causes hypercalcaemia with low phosphate, not the normal calcium and phosphate profile described in this patient.', 4),
('c5000000-0000-0000-0000-000000000013', 'E', 'Osteoporosis', false, 'Ruled out because osteoporosis does not cause a raised ALP or the localised bone deformity and mixed radiographic pattern described here; it is a disorder of bone density with normal biochemistry.', 5),
('c5000000-0000-0000-0000-000000000014', 'A', 'No specific bone health assessment is needed unless she sustains a fragility fracture', false, 'Ruled out because in glucocorticoid-induced bone loss, proactive assessment and often prophylactic bone protection is recommended precisely to prevent the first fragility fracture, not only after one occurs.', 1),
('c5000000-0000-0000-0000-000000000014', 'B', 'Stop the prednisolone immediately to prevent further bone loss', false, 'Ruled out because giant cell arteritis requires ongoing steroid treatment to prevent serious complications such as blindness; steroids should not be stopped abruptly for bone health reasons, and doing so risks disease relapse and adrenal insufficiency.', 2),
('c5000000-0000-0000-0000-000000000014', 'C', 'Assess fracture risk formally (e.g. with a FRAX score incorporating glucocorticoid use) and consider bone-protective treatment without waiting for a fracture to occur', true, 'Correct. Long-term glucocorticoid therapy is a major independent risk factor for osteoporosis and fragility fracture, acting both by reducing bone formation and increasing bone resorption. Patients on long-term steroids should have their fracture risk formally assessed (rather than waiting for a fracture), with bone-protective therapy (typically a bisphosphonate) considered proactively, especially in older patients or those on higher doses.', 3),
('c5000000-0000-0000-0000-000000000014', 'D', 'Arrange calcium and vitamin D supplementation only, with no further risk assessment', false, 'Ruled out because supplementation alone, without formal fracture risk assessment and consideration of bone-protective therapy, is inadequate for a patient on long-term steroids with elevated fracture risk.', 4),
('c5000000-0000-0000-0000-000000000014', 'E', 'Reassure her that steroid-induced bone loss does not increase fracture risk if calcium levels are normal', false, 'Ruled out because glucocorticoid-induced osteoporosis occurs independently of serum calcium and significantly increases fracture risk; normal calcium does not indicate normal bone density.', 5),
('c5000000-0000-0000-0000-000000000015', 'A', 'Lifestyle advice alone, with no medication until HbA1c exceeds 75 mmol/mol', false, 'Ruled out because metformin is recommended alongside lifestyle measures at diagnosis of type 2 diabetes, not deferred until a much higher HbA1c threshold.', 1),
('c5000000-0000-0000-0000-000000000015', 'B', 'Start insulin therapy immediately', false, 'Ruled out because insulin is not first-line for newly diagnosed, asymptomatic type 2 diabetes; oral metformin with lifestyle changes is the appropriate initial approach.', 2),
('c5000000-0000-0000-0000-000000000015', 'C', 'Start a sulfonylurea (e.g. gliclazide) as first-line therapy', false, 'Ruled out because metformin is first-line for type 2 diabetes due to its favourable side-effect profile (no hypoglycaemia risk, weight neutral); sulfonylureas are typically second-line.', 3),
('c5000000-0000-0000-0000-000000000015', 'D', 'Lifestyle advice (diet and exercise) alongside starting metformin', true, 'Correct. A fasting plasma glucose >=7.0 mmol/L on two occasions confirms a diagnosis of type 2 diabetes mellitus. First-line management combines lifestyle modification (weight loss, diet, exercise) with metformin, unless contraindicated, as recommended by national guidance.', 4),
('c5000000-0000-0000-0000-000000000015', 'E', 'Refer for bariatric surgery as the primary management', false, 'Ruled out because bariatric surgery is considered in select patients with more severe obesity and/or after failure of medical management, not as first-line therapy for newly diagnosed diabetes.', 5),
('c5000000-0000-0000-0000-000000000016', 'A', 'A second random glucose test is required a week later before diagnosis can be made', false, 'Ruled out because a repeat confirmatory test is only necessary in asymptomatic patients; this patient has classic osmotic symptoms of hyperglycaemia, so one diagnostic result is sufficient.', 1),
('c5000000-0000-0000-0000-000000000016', 'B', 'No further confirmatory test is needed; a diagnosis of diabetes can be made because she has classic hyperglycaemic symptoms with a random glucose >=11.1 mmol/L', true, 'Correct. In a symptomatic patient (polyuria, polydipsia), a single random venous plasma glucose >=11.1 mmol/L (or fasting glucose >=7.0 mmol/L, or HbA1c >=48 mmol/mol) is sufficient to diagnose diabetes; a second confirmatory test is only required in asymptomatic individuals.', 2),
('c5000000-0000-0000-0000-000000000016', 'C', 'An oral glucose tolerance test must be performed before a diagnosis can be made', false, 'Ruled out because an OGTT is not required when a symptomatic patient already meets diagnostic glucose criteria; it is more typically used for diagnosing gestational diabetes or borderline/impaired glucose tolerance.', 3),
('c5000000-0000-0000-0000-000000000016', 'D', 'A diagnosis cannot be made until a fasting glucose is obtained', false, 'Ruled out because a random glucose >=11.1 mmol/L in a symptomatic patient is diagnostic on its own; a fasting sample is not mandatory in this context.', 4),
('c5000000-0000-0000-0000-000000000016', 'E', 'HbA1c must be measured and used exclusively, as random glucose is not a valid diagnostic criterion', false, 'Ruled out because random venous plasma glucose >=11.1 mmol/L in a symptomatic patient is a valid, WHO-recognised diagnostic criterion for diabetes in its own right.', 5),
('c5000000-0000-0000-0000-000000000017', 'A', 'Type 2 diabetes mellitus', false, $x$Ruled out because type 2 diabetes typically presents in older, overweight patients with a more insidious onset and is less commonly associated with significant ketonuria at presentation; this patient's age, low BMI, and acute presentation favour type 1.$x$, 1),
('c5000000-0000-0000-0000-000000000017', 'B', 'Maturity-onset diabetes of the young (MODY)', false, $x$Ruled out because MODY typically has a strong family history across multiple generations and a milder, more insidious presentation without significant ketosis, unlike this patient's acute symptomatic presentation.$x$, 2),
('c5000000-0000-0000-0000-000000000017', 'C', 'Diabetes insipidus', false, 'Ruled out because diabetes insipidus causes polyuria and polydipsia due to impaired renal water handling, with normal (not markedly elevated) blood glucose and no glycosuria/ketonuria.', 3),
('c5000000-0000-0000-0000-000000000017', 'D', 'Gestational diabetes', false, $x$Ruled out because this diagnosis only applies during pregnancy, which is not mentioned in this patient's history.$x$, 4),
('c5000000-0000-0000-0000-000000000017', 'E', 'Type 1 diabetes mellitus', true, 'Correct. A young, lean patient with an acute onset of osmotic symptoms, weight loss, marked hyperglycaemia, and ketonuria (without severe acidosis at this point) is typical of new-onset type 1 diabetes, caused by autoimmune destruction of pancreatic beta cells leading to absolute insulin deficiency.', 5),
('c5000000-0000-0000-0000-000000000018', 'A', 'Continue metformin at the same dose, as it has no relevant renal toxicity', false, 'Ruled out because metformin accumulation in significant renal impairment increases the risk of lactic acidosis; dose adjustment or cessation is required as renal function declines.', 1),
('c5000000-0000-0000-0000-000000000018', 'B', 'Increase the metformin dose to improve glycaemic control given his declining renal function', false, 'Ruled out because increasing the dose in the context of significant renal impairment would further increase the risk of metformin accumulation and lactic acidosis.', 2),
('c5000000-0000-0000-0000-000000000018', 'C', 'Switch metformin to modified-release formulation only, with no dose reduction', false, 'Ruled out because a modified-release formulation does not address the underlying renal excretion problem; the eGFR here is low enough that metformin should be stopped, not merely reformulated.', 3),
('c5000000-0000-0000-0000-000000000018', 'D', 'Stop metformin, as it is contraindicated at this level of renal impairment', true, 'Correct. Metformin is renally excreted, and its accumulation in significant renal impairment (eGFR below approximately 30 mL/min/1.73m^2) increases the risk of lactic acidosis, a rare but potentially fatal complication. At this eGFR, metformin should be stopped and an alternative glucose-lowering agent considered.', 4),
('c5000000-0000-0000-0000-000000000018', 'E', 'Continue metformin but add high-dose diuretics to protect renal function', false, $x$Ruled out because diuretics do not mitigate metformin's renal-excretion-dependent risk of accumulation, and this response does not address the core issue of significant renal impairment.$x$, 5),
('c5000000-0000-0000-0000-000000000019', 'A', 'Classify him as at moderate/high risk for diabetic foot complications and refer for ongoing foot surveillance/education, with clear safety-netting advice', true, 'Correct. Loss of protective sensation (abnormal monofilament and vibration testing) despite palpable pulses indicates peripheral neuropathy, placing him at increased risk of unnoticed trauma, ulceration, and subsequent complications. He requires appropriate risk stratification, foot care education, and more frequent surveillance, even though he is currently asymptomatic and has no active ulcer.', 1),
('c5000000-0000-0000-0000-000000000019', 'B', 'Reassure him that no action is needed since he is currently asymptomatic and pulses are present', false, 'Ruled out because loss of protective sensation from neuropathy is itself a significant risk factor for foot ulceration, regardless of current symptoms or pulse status, and requires proactive risk stratification and education.', 2),
('c5000000-0000-0000-0000-000000000019', 'C', 'Arrange urgent referral to vascular surgery for revascularisation', false, 'Ruled out because pedal pulses are palpable, suggesting adequate arterial supply currently; urgent vascular referral is not indicated in the absence of critical limb ischaemia or absent pulses.', 3),
('c5000000-0000-0000-0000-000000000019', 'D', 'Start empirical antibiotics for suspected infection', false, 'Ruled out because there is no evidence of infection (no ulcer, wound or signs of cellulitis described); antibiotics are not indicated here.', 4),
('c5000000-0000-0000-0000-000000000019', 'E', 'Arrange amputation assessment given his high risk of complications', false, 'Ruled out because this is a grossly disproportionate response to a patient with sensory neuropathy but no ulceration, infection, or critical ischaemia; risk stratification and preventive foot care are appropriate instead.', 5),
('c5000000-0000-0000-0000-000000000020', 'A', 'Start insulin immediately, as this is mandatory for any diagnosis of gestational diabetes', false, 'Ruled out because immediate insulin is not required for all gestational diabetes; dietary/lifestyle measures are trialled first when fasting glucose is below higher thresholds, escalating to medication only if targets are not met.', 1),
('c5000000-0000-0000-0000-000000000020', 'B', 'Reassure her that gestational diabetes does not require any specific management and will resolve after delivery', false, 'Ruled out because untreated gestational diabetes increases risks of macrosomia, birth complications, and neonatal hypoglycaemia; active management during pregnancy is required even though it typically resolves after delivery.', 2),
('c5000000-0000-0000-0000-000000000020', 'C', 'Trial of dietary and lifestyle changes with self-monitoring of blood glucose, escalating to metformin and/or insulin if glucose targets are not met', true, 'Correct. First-line management of gestational diabetes with fasting glucose below 7 mmol/L is a trial of diet and exercise with home glucose monitoring; if glucose targets are not achieved within 1-2 weeks, pharmacological treatment (metformin and/or insulin) is added. This stepwise approach avoids unnecessary medication while ensuring good glycaemic control to reduce risks such as macrosomia.', 3),
('c5000000-0000-0000-0000-000000000020', 'D', 'Arrange termination of pregnancy due to the diagnosis of diabetes', false, 'Ruled out because gestational diabetes is a common and manageable condition; it is not an indication for termination of pregnancy.', 4),
('c5000000-0000-0000-0000-000000000020', 'E', 'Start a sulfonylurea as first-line pharmacological therapy', false, 'Ruled out because when medication is required, metformin and/or insulin are the preferred agents in gestational diabetes; sulfonylureas are not first-line in this context.', 5),
('c5000000-0000-0000-0000-000000000021', 'A', 'Urgent same-day ophthalmology referral', false, 'Ruled out because background (non-proliferative) retinopathy without features of sight-threatening disease (e.g. proliferative changes, macular oedema, vitreous haemorrhage) does not require urgent same-day referral.', 1),
('c5000000-0000-0000-0000-000000000021', 'B', 'Immediate laser photocoagulation therapy', false, 'Ruled out because laser photocoagulation is reserved for proliferative retinopathy or other sight-threatening features, not mild background changes.', 2),
('c5000000-0000-0000-0000-000000000021', 'C', 'Continue routine annual diabetic retinopathy screening, with optimisation of glycaemic and blood pressure control', true, 'Correct. Microaneurysms and blot haemorrhages without neovascularisation or macular oedema represent background (non-proliferative) diabetic retinopathy. This does not require urgent ophthalmology referral; management is continued annual screening alongside optimising glycaemic control, blood pressure, and other risk factors to slow progression.', 3),
('c5000000-0000-0000-0000-000000000021', 'D', 'Stop all diabetic medications as the retinopathy indicates overtreatment', false, 'Ruled out because retinopathy is a microvascular complication of diabetes duration and control, not a sign of medication overtreatment; his diabetes treatment should continue, with optimisation of control if needed.', 4),
('c5000000-0000-0000-0000-000000000021', 'E', 'No further retinal screening is required now that a diagnosis of retinopathy has been made', false, 'Ruled out because ongoing regular screening is essential to detect any progression to more severe or sight-threatening retinopathy over time.', 5),
('c5000000-0000-0000-0000-000000000022', 'A', 'Subcutaneous rapid-acting insulin and encourage oral fluids', false, 'Ruled out because DKA is a medical emergency requiring IV fluids and a fixed-rate IV (not subcutaneous) insulin infusion for reliable, controlled correction of hyperglycaemia and ketosis; oral fluids are inadequate given her clinical state.', 1),
('c5000000-0000-0000-0000-000000000022', 'B', 'Administer IV sodium bicarbonate to correct the acidosis prior to fluids or insulin', false, 'Ruled out because bicarbonate is not routinely used in DKA management; the acidosis corrects as ketogenesis is switched off with fluids and insulin therapy.', 2),
('c5000000-0000-0000-0000-000000000022', 'C', 'Withhold insulin until the potassium level is confirmed normal', false, 'Ruled out because insulin is a core part of DKA treatment; potassium is monitored and replaced alongside insulin therapy (once potassium is known and if not already dangerously high), not withheld while awaiting results, as this would delay essential treatment.', 3),
('c5000000-0000-0000-0000-000000000022', 'D', 'Give oral potassium supplementation and discharge with GP follow-up once glucose falls below 15 mmol/L', false, 'Ruled out because a patient with DKA of this severity (pH 7.12, significant ketosis) requires inpatient management with IV fluids, insulin, and monitoring until resolution, not discharge based on glucose alone.', 4),
('c5000000-0000-0000-0000-000000000022', 'E', 'IV 0.9% sodium chloride fluid resuscitation followed by a fixed-rate IV insulin infusion, with regular monitoring of glucose, ketones, and potassium', true, 'Correct. This is diabetic ketoacidosis (hyperglycaemia, ketosis, and metabolic acidosis), precipitated by insulin dose reduction during illness. Immediate management is IV fluid resuscitation (to correct dehydration and improve perfusion) followed by a fixed-rate IV insulin infusion to switch off ketogenesis, with close monitoring of glucose, ketones, and potassium (as insulin drives potassium into cells and can cause dangerous hypokalaemia if not replaced).', 5),
('c5000000-0000-0000-0000-000000000023', 'A', 'Diabetic ketoacidosis', false, 'Ruled out because DKA requires significant ketosis and metabolic acidosis, neither of which are present here (normal pH/bicarbonate, minimal ketones); this pattern fits HHS instead.', 1),
('c5000000-0000-0000-0000-000000000023', 'B', 'Hyperosmolar hyperglycaemic state (HHS)', true, 'Correct. Marked hyperglycaemia, severe dehydration, high serum osmolality, and confusion, with normal pH/bicarbonate and only mildly raised ketones (no significant acidosis or ketosis), in an elderly patient with type 2 diabetes, is the classic picture of HHS, which develops over days due to relative (not absolute) insulin deficiency.', 2),
('c5000000-0000-0000-0000-000000000023', 'C', 'Hypoglycaemia', false, 'Ruled out because her capillary glucose is markedly elevated (42 mmol/L), not low, which excludes hypoglycaemia.', 3),
('c5000000-0000-0000-0000-000000000023', 'D', 'Lactic acidosis secondary to metformin accumulation', false, 'Ruled out because she is not on metformin, and her blood gas shows a normal pH and bicarbonate, inconsistent with a significant metabolic acidosis.', 4),
('c5000000-0000-0000-0000-000000000023', 'E', 'Acute stroke', false, 'Ruled out because although confusion can occur in stroke, the biochemical picture here (marked hyperglycaemia, dehydration, hyperosmolality) is diagnostic of a metabolic emergency (HHS) rather than a primary neurological event; HHS itself should be treated and stroke considered only if focal neurology or other red flags are present.', 5),
('c5000000-0000-0000-0000-000000000024', 'A', 'Oral glucose gel rubbed into the buccal mucosa as first-line treatment', false, 'Ruled out because he is unresponsive and unable to swallow safely; giving anything by mouth risks aspiration. Parenteral treatment (IM glucagon or IV glucose) is required.', 1),
('c5000000-0000-0000-0000-000000000024', 'B', 'Give his usual dose of rapid-acting insulin to prevent rebound hyperglycaemia', false, 'Ruled out because giving insulin during severe hypoglycaemia would be dangerous and worsen his condition; glucose/glucagon must be given to correct the hypoglycaemia first.', 2),
('c5000000-0000-0000-0000-000000000024', 'C', 'Withhold treatment until a formal venous glucose sample confirms the capillary reading', false, 'Ruled out because severe symptomatic hypoglycaemia with reduced consciousness should be treated immediately based on the capillary reading; delaying treatment for confirmatory venous sampling risks harm.', 3),
('c5000000-0000-0000-0000-000000000024', 'D', 'Intramuscular glucagon or IV 10-20% glucose, with reassessment of conscious level and repeat glucose once treated', true, 'Correct. In severe hypoglycaemia with impaired consciousness and an unsafe swallow, oral glucose is contraindicated due to aspiration risk. IM glucagon (if IV access is unavailable) or IV glucose (if access is available) are appropriate emergency treatments, followed by close reassessment as hypoglycaemia can recur, particularly after glucagon.', 4),
('c5000000-0000-0000-0000-000000000024', 'E', 'Place him in the recovery position and observe without active treatment, as hypoglycaemia will self-correct', false, 'Ruled out because severe hypoglycaemia with unconsciousness will not reliably self-correct and requires active treatment (glucagon/IV glucose) to prevent seizures, coma, or death.', 5),
('c5000000-0000-0000-0000-000000000025', 'A', 'Add potassium chloride to the IV fluids according to local protocol, while continuing the insulin infusion and monitoring potassium closely', true, 'Correct. Insulin drives potassium into cells, and combined with ongoing osmotic diuresis, this causes a predictable fall in serum potassium during DKA treatment, even when the admission potassium was normal or high (as total body potassium is often already depleted). Potassium must be added to replacement fluids once levels fall below the normal range (and monitored closely) to prevent life-threatening hypokalaemia and arrhythmia, while insulin is continued as it remains essential to resolve the ketoacidosis.', 1),
('c5000000-0000-0000-0000-000000000025', 'B', 'Stop the insulin infusion immediately because of the falling potassium', false, 'Ruled out because stopping insulin would halt resolution of the ketoacidosis; the correct response to falling potassium is to add potassium replacement to the fluids, not to stop insulin.', 2),
('c5000000-0000-0000-0000-000000000025', 'C', 'Continue fluids without any potassium replacement, as his admission potassium was normal', false, 'Ruled out because potassium can fall rapidly and unpredictably once insulin therapy begins in DKA, regardless of the admission value; regular monitoring and timely replacement are essential parts of the protocol.', 3),
('c5000000-0000-0000-0000-000000000025', 'D', 'Give a stat dose of IV calcium gluconate to manage the hypokalaemia', false, 'Ruled out because IV calcium gluconate is used to treat hyperkalaemia-related cardiac membrane stabilisation, not hypokalaemia; potassium replacement in the fluids is the correct treatment here.', 4),
('c5000000-0000-0000-0000-000000000025', 'E', 'Switch to oral potassium supplementation only, discontinuing IV fluids', false, 'Ruled out because he still requires ongoing IV fluid and insulin therapy for DKA resolution; IV potassium replacement within the fluid regimen, not oral supplementation alone, is appropriate at this stage.', 5),
('c5000000-0000-0000-0000-000000000026', 'A', 'Take 15-20g of fast-acting oral carbohydrate (e.g. glucose tablets or a sugary drink), recheck glucose after 15 minutes, and do not drive until glucose has normalised', true, 'Correct. In mild-to-moderate hypoglycaemia with intact consciousness and a safe swallow, oral fast-acting carbohydrate is the appropriate first step, followed by rechecking glucose to confirm resolution before eating a longer-acting carbohydrate snack. She must not drive with hypoglycaemia; DVLA guidance requires blood glucose to be safely above the driving threshold before continuing a journey.', 1),
('c5000000-0000-0000-0000-000000000026', 'B', 'Continue driving immediately, as she feels only mildly symptomatic', false, 'Ruled out because driving with hypoglycaemia is unsafe and against DVLA guidance; she should treat the hypoglycaemia and confirm normalisation of glucose before resuming driving.', 2),
('c5000000-0000-0000-0000-000000000026', 'C', 'Administer intramuscular glucagon immediately', false, 'Ruled out because she is conscious, alert, and able to swallow safely; oral carbohydrate is appropriate and glucagon is reserved for severe hypoglycaemia with impaired consciousness or unsafe swallow.', 3),
('c5000000-0000-0000-0000-000000000026', 'D', 'Increase her next insulin dose to prevent rebound hyperglycaemia', false, 'Ruled out because increasing insulin during hypoglycaemia would worsen the low glucose and is dangerous; the priority is treating the current hypoglycaemia with carbohydrate.', 4),
('c5000000-0000-0000-0000-000000000026', 'E', 'Withhold all carbohydrate and monitor glucose hourly until it rises spontaneously', false, 'Ruled out because active treatment with fast-acting carbohydrate is recommended rather than passive observation, to correct hypoglycaemia promptly and safely.', 5),
('c5000000-0000-0000-0000-000000000027', 'A', 'He should stop his insulin completely until he is eating normally again', false, 'Ruled out because stopping insulin in type 1 diabetes during illness is dangerous and can rapidly precipitate diabetic ketoacidosis, regardless of reduced oral intake.', 1),
('c5000000-0000-0000-0000-000000000027', 'B', 'He should halve his usual insulin doses for the duration of the illness', false, 'Ruled out because illness typically increases (not decreases) insulin requirements due to physiological stress hormones; reducing the dose risks ketosis and DKA.', 2),
('c5000000-0000-0000-0000-000000000027', 'C', 'He only needs to monitor his glucose once daily during the illness', false, 'Ruled out because illness requires more frequent glucose and ketone monitoring (not less) to detect early deterioration and adjust insulin appropriately.', 3),
('c5000000-0000-0000-0000-000000000027', 'D', 'He should never stop his insulin during illness; doses may need adjusting (often increasing) and he should check his blood glucose and ketones more frequently', true, $x$Correct. Illness increases insulin requirements due to the physiological stress response, even when oral intake is reduced. Stopping insulin in type 1 diabetes risks rapid development of diabetic ketoacidosis, since these patients have absolute insulin deficiency. 'Sick day rules' emphasise continuing (and often increasing) insulin, increased frequency of glucose and ketone monitoring, and maintaining hydration/carbohydrate intake where possible.$x$, 4),
('c5000000-0000-0000-0000-000000000027', 'E', 'He should switch entirely from insulin to oral hypoglycaemic tablets during the illness', false, 'Ruled out because type 1 diabetes is due to absolute insulin deficiency; oral hypoglycaemic agents are not an appropriate substitute for insulin at any time, particularly not during acute illness.', 5),
('c5000000-0000-0000-0000-000000000028', 'A', 'No further action is needed beyond fluids and insulin, as these will resolve the underlying infection as well', false, 'Ruled out because fluids and insulin treat the metabolic derangement of DKA but do not treat an underlying bacterial infection; specific antimicrobial therapy is required for the urinary tract infection.', 1),
('c5000000-0000-0000-0000-000000000028', 'B', 'Delay antibiotics until the DKA has fully resolved to avoid drug interactions with insulin', false, 'Ruled out because untreated infection will perpetuate the physiological stress driving the DKA; antibiotics should be started promptly alongside DKA treatment, not delayed.', 2),
('c5000000-0000-0000-0000-000000000028', 'C', 'Perform an urgent CT abdomen to look for a surgical cause before starting antibiotics', false, 'Ruled out because the clinical picture already points to a urinary tract infection as the likely precipitant; there is no indication here for urgent abdominal imaging before starting appropriate antibiotics.', 3),
('c5000000-0000-0000-0000-000000000028', 'D', 'Reduce the insulin infusion rate to allow the infection to resolve first', false, 'Ruled out because the insulin infusion is essential to resolve the ketoacidosis itself and should be continued (per protocol, adjusted based on glucose/ketone trends) regardless of concurrent antibiotic treatment for the infection.', 4),
('c5000000-0000-0000-0000-000000000028', 'E', 'Identify and treat the underlying precipitant, in this case starting appropriate antibiotics for the urinary tract infection', true, 'Correct. DKA is almost always triggered by an underlying precipitant (commonly infection, missed insulin, or new diagnosis); identifying and treating this precipitant, here a urinary tract infection with appropriate antibiotics, is essential alongside standard DKA management (fluids and insulin) to achieve resolution and prevent recurrence.', 5),
('c5000000-0000-0000-0000-000000000029', 'A', 'Metabolic syndrome', false, 'Ruled out because metabolic syndrome is characterised by a cluster of obesity, hypertension, dyslipidaemia (typically raised triglycerides and low HDL rather than markedly raised LDL), and insulin resistance, not the specific pattern of very high LDL with tendon xanthomata and strong family history described here.', 1),
('c5000000-0000-0000-0000-000000000029', 'B', 'Nephrotic syndrome', false, 'Ruled out because although nephrotic syndrome can cause hyperlipidaemia, there is no mention of oedema, proteinuria, or hypoalbuminaemia, and it does not typically cause tendon xanthomata or this pattern of strong family history.', 2),
('c5000000-0000-0000-0000-000000000029', 'C', 'Familial hypercholesterolaemia', true, 'Correct. Markedly elevated LDL cholesterol, tendon xanthomata, and a strong family history of premature coronary artery disease are classic features of familial hypercholesterolaemia, an autosomal dominant condition typically caused by mutations affecting the LDL receptor, leading to lifelong markedly elevated LDL cholesterol and greatly increased cardiovascular risk from a young age.', 3),
('c5000000-0000-0000-0000-000000000029', 'D', 'Hypothyroidism', false, 'Ruled out because although hypothyroidism can raise cholesterol, it would not explain the tendon xanthomata or the strong family history of premature coronary disease seen here; this presentation is much more specific for a primary genetic lipid disorder.', 4),
('c5000000-0000-0000-0000-000000000029', 'E', 'Alcohol-related dyslipidaemia', false, 'Ruled out because alcohol excess typically raises triglycerides more than LDL cholesterol and would not produce tendon xanthomata or the described family pattern of premature cardiac events.', 5),
('c5000000-0000-0000-0000-000000000030', 'A', 'No statin is indicated, as he has no history of cardiovascular disease', false, 'Ruled out because statins for primary prevention are offered based on estimated future cardiovascular risk (QRISK score), not only after a cardiovascular event has already occurred; his risk score here meets the threshold for treatment.', 1),
('c5000000-0000-0000-0000-000000000030', 'B', 'Offer atorvastatin 20 mg for primary prevention of cardiovascular disease', true, 'Correct. A QRISK3 score of 10% or more indicates a sufficiently high estimated 10-year cardiovascular risk to offer statin therapy for primary prevention, per national guidance. Atorvastatin 20 mg is the standard first-line dose for primary prevention.', 2),
('c5000000-0000-0000-0000-000000000030', 'C', 'Start atorvastatin 80 mg, as used for secondary prevention', false, $x$Ruled out because the higher dose (80 mg) is generally reserved for secondary prevention (established cardiovascular disease); this patient's presentation is a primary prevention scenario, for which a starting dose of 20 mg is appropriate.$x$, 3),
('c5000000-0000-0000-0000-000000000030', 'D', 'Recommend lifestyle changes only, deferring any statin decision until his QRISK score exceeds 20%', false, 'Ruled out because the recommended threshold for offering statin therapy in primary prevention is a 10-year risk of 10% or more, not 20%; his current score already meets this threshold.', 4),
('c5000000-0000-0000-0000-000000000030', 'E', 'Start a fibrate as first-line lipid-lowering therapy', false, 'Ruled out because statins, not fibrates, are first-line for primary prevention of cardiovascular disease based on elevated cardiovascular risk; fibrates are typically reserved for severe hypertriglyceridaemia.', 5),
('c5000000-0000-0000-0000-000000000031', 'A', 'Continue the statin at the same dose, as muscle aches are a trivial and expected side effect', false, 'Ruled out because a markedly elevated CK with significant symptoms indicates clinically significant myopathy, which risks progressing to rhabdomyolysis and acute kidney injury if the statin is continued; this is not a trivial side effect to be ignored.', 1),
('c5000000-0000-0000-0000-000000000031', 'B', 'Stop the statin and investigate further, monitoring renal function and CK closely', true, 'Correct. Significant muscle symptoms with markedly elevated CK in a patient on a statin indicates statin-induced myopathy, which can progress to rhabdomyolysis with acute kidney injury if the drug is continued. The statin should be stopped, with monitoring of renal function and CK, before considering an alternative lipid-lowering strategy once symptoms resolve.', 2),
('c5000000-0000-0000-0000-000000000031', 'C', 'Increase the statin dose to assess whether symptoms are dose-related', false, 'Ruled out because increasing the dose in the presence of significant myopathy and markedly raised CK would worsen the risk of rhabdomyolysis, not clarify the diagnosis.', 3),
('c5000000-0000-0000-0000-000000000031', 'D', 'Switch immediately to a fibrate without stopping the statin first', false, 'Ruled out because combining a statin with a fibrate while myopathy is present increases the risk of rhabdomyolysis further; the statin must be stopped first and the patient assessed before considering alternative therapy.', 4),
('c5000000-0000-0000-0000-000000000031', 'E', 'Reassure her and arrange routine follow-up in three months with no interim changes', false, 'Ruled out because a markedly elevated CK with significant muscle symptoms requires prompt action (stopping the statin, checking renal function) rather than routine deferred follow-up, given the risk of progression to rhabdomyolysis.', 5),
('c5000000-0000-0000-0000-000000000032', 'A', 'High-intensity statin therapy (e.g. atorvastatin 80 mg)', true, 'Correct. Following an acute coronary syndrome, high-intensity statin therapy (such as atorvastatin 80 mg) is recommended for secondary prevention, regardless of the baseline cholesterol level, to reduce the risk of recurrent cardiovascular events.', 1),
('c5000000-0000-0000-0000-000000000032', 'B', 'Low-intensity statin therapy (e.g. simvastatin 10 mg)', false, 'Ruled out because low-intensity statin doses are inadequate for secondary prevention after an acute coronary syndrome; high-intensity therapy is recommended in this context.', 2),
('c5000000-0000-0000-0000-000000000032', 'C', 'No statin therapy, as his LDL cholesterol is not significantly elevated', false, 'Ruled out because statin therapy for secondary prevention after a myocardial infarction is recommended regardless of baseline LDL level, given the substantially increased cardiovascular risk following an acute event.', 3),
('c5000000-0000-0000-0000-000000000032', 'D', 'Fibrate monotherapy as first-line secondary prevention', false, 'Ruled out because statins, not fibrates, are first-line for secondary cardiovascular prevention; fibrates are generally reserved for severe hypertriglyceridaemia.', 4),
('c5000000-0000-0000-0000-000000000032', 'E', 'Dietary modification alone, deferring pharmacological therapy for six months', false, 'Ruled out because high-intensity statin therapy should be started promptly after an acute coronary syndrome, alongside lifestyle measures, not deferred.', 5),
('c5000000-0000-0000-0000-000000000033', 'A', 'Clarithromycin has no clinically significant interaction with simvastatin and both can be continued as normal', false, 'Ruled out because this is a well-recognised, clinically significant interaction (via CYP3A4 inhibition) that substantially raises the risk of statin-induced myopathy and rhabdomyolysis.', 1),
('c5000000-0000-0000-0000-000000000033', 'B', 'Simvastatin reduces the antibacterial efficacy of clarithromycin', false, 'Ruled out because the clinically important interaction runs in the opposite direction: clarithromycin raises simvastatin levels via enzyme inhibition, not the reverse.', 2),
('c5000000-0000-0000-0000-000000000033', 'C', 'Clarithromycin inhibits CYP3A4 metabolism of simvastatin, significantly increasing simvastatin levels and the risk of myopathy/rhabdomyolysis; the statin should be withheld during the antibiotic course', true, 'Correct. Macrolides such as clarithromycin and erythromycin are potent inhibitors of CYP3A4, the enzyme responsible for metabolising simvastatin (and, to a lesser extent, atorvastatin). Co-administration markedly raises simvastatin plasma levels, substantially increasing the risk of myopathy and rhabdomyolysis; guidance is to withhold the statin during and shortly after a course of an interacting macrolide, or choose a non-interacting antibiotic/statin where possible.', 3),
('c5000000-0000-0000-0000-000000000033', 'D', 'The combination increases the risk of QT prolongation as the primary concern, rather than myopathy', false, 'Ruled out because while macrolides can independently prolong the QT interval, the specific, well-recognised interaction with simvastatin relates to CYP3A4 inhibition raising statin levels and myopathy/rhabdomyolysis risk, which is the key safety issue here.', 4),
('c5000000-0000-0000-0000-000000000033', 'E', 'Clarithromycin should be avoided solely because it reduces absorption of simvastatin, reducing its efficacy', false, 'Ruled out because the interaction increases (not decreases) simvastatin levels via metabolic inhibition, raising toxicity risk rather than reducing efficacy.', 5),
('c5000000-0000-0000-0000-000000000034', 'A', 'The lipid abnormality is an incidental, unrelated finding with no bearing on his pancreatitis', false, 'Ruled out because severe hypertriglyceridaemia at this level is a recognised direct cause of acute pancreatitis, not merely an incidental finding.', 1),
('c5000000-0000-0000-0000-000000000034', 'B', 'His grossly elevated triglycerides are solely a consequence of the pancreatitis itself and will resolve without specific treatment', false, 'Ruled out because although acute illness can transiently affect lipids, triglycerides at this markedly elevated level (32 mmol/L) more likely represent a pre-existing severe hypertriglyceridaemia that has caused the pancreatitis, and this typically requires specific treatment to reduce recurrence risk.', 2),
('c5000000-0000-0000-0000-000000000034', 'C', 'Amylase elevation is caused by the hypertriglyceridaemia directly, independent of any pancreatic inflammation', false, 'Ruled out because amylase elevation in this context reflects pancreatic inflammation (pancreatitis) itself, of which the hypertriglyceridaemia is considered a causative factor, not a direct, separate cause of amylase elevation.', 3),
('c5000000-0000-0000-0000-000000000034', 'D', 'Severe hypertriglyceridaemia is a recognised cause of acute pancreatitis', true, 'Correct. Severe hypertriglyceridaemia (typically triglycerides above around 11.3 mmol/L, and especially at this markedly elevated level) is a well-established cause of acute pancreatitis, thought to result from free fatty acid-induced injury to pancreatic acinar cells and capillaries. Risk factors including poorly controlled diabetes and alcohol excess (both of which raise triglycerides) commonly coexist with this presentation.', 4),
('c5000000-0000-0000-0000-000000000034', 'E', 'Hypertriglyceridaemia at this level is a normal finding in poorly controlled diabetes and requires no further evaluation', false, 'Ruled out because although diabetes can raise triglycerides, a level this markedly elevated is abnormal even in poorly controlled diabetes and requires active management given its role in causing pancreatitis and its association with future recurrence.', 5),
('c5000000-0000-0000-0000-000000000035', 'A', 'No family testing is needed, as familial hypercholesterolaemia is not an inherited condition', false, 'Ruled out because familial hypercholesterolaemia is an autosomal dominant inherited condition, and family members are at significant risk of also being affected.', 1),
('c5000000-0000-0000-0000-000000000035', 'B', 'Only his children need to be tested, as the condition cannot be inherited from a parent', false, 'Ruled out because inheritance can come from either parent, and all first-degree relatives (parents, siblings, and children) are at 50% risk and should be offered testing, not children alone.', 2),
('c5000000-0000-0000-0000-000000000035', 'C', 'Testing should be deferred until relatives develop symptoms of cardiovascular disease', false, 'Ruled out because the purpose of cascade testing is to identify at-risk relatives before they develop cardiovascular disease, allowing early treatment to reduce risk; waiting for symptoms defeats this preventive purpose.', 3),
('c5000000-0000-0000-0000-000000000035', 'D', 'Genetic testing is mandatory for all relatives regardless of lipid levels, and lipid testing alone is never sufficient', false, 'Ruled out because cascade testing can use either genetic testing (if the causative mutation is known) or lipid profile testing with clinical criteria; genetic testing is helpful but not always mandatory for every relative.', 4),
('c5000000-0000-0000-0000-000000000035', 'E', 'Offer cascade testing to his first-degree relatives (parents, siblings, children), extending to more distant relatives if they are also found to be affected', true, 'Correct. Familial hypercholesterolaemia is autosomal dominant, meaning first-degree relatives have a 50% chance of carrying the same mutation/condition. Cascade testing (systematically testing relatives of confirmed cases, starting with first-degree relatives and extending outward through the family if further affected relatives are found) is the recommended and most effective way to identify affected individuals early, allowing prompt treatment to reduce their cardiovascular risk.', 5),
('c5000000-0000-0000-0000-000000000036', 'A', 'A dopamine agonist (e.g. cabergoline)', true, 'Correct. This presentation (amenorrhoea, galactorrhoea, markedly raised prolactin, and a pituitary lesion) is a prolactinoma. Dopamine agonists (cabergoline or bromocriptine) are first-line treatment, as they suppress prolactin secretion, restore gonadal function, and typically shrink the tumour, avoiding the need for surgery in most cases.', 1),
('c5000000-0000-0000-0000-000000000036', 'B', 'Transsphenoidal surgical resection as first-line treatment', false, 'Ruled out because unlike other pituitary adenomas, prolactinomas are managed medically first with dopamine agonists, which are usually highly effective; surgery is reserved for cases resistant to or intolerant of medical therapy.', 2),
('c5000000-0000-0000-0000-000000000036', 'C', 'External beam radiotherapy as first-line treatment', false, 'Ruled out because radiotherapy is not first-line for prolactinoma; it is reserved for cases not controlled by medical therapy or surgery.', 3),
('c5000000-0000-0000-0000-000000000036', 'D', 'Combined oral contraceptive pill to restore her menstrual cycle', false, 'Ruled out because this would not address the underlying prolactinoma or reduce prolactin levels, and does not treat the cause of her galactorrhoea and amenorrhoea.', 4),
('c5000000-0000-0000-0000-000000000036', 'E', 'Observation only, with no treatment unless she wishes to conceive', false, 'Ruled out because untreated hyperprolactinaemia causes ongoing hypogonadism (with associated bone density risks) and the tumour may enlarge; treatment with a dopamine agonist is indicated regardless of fertility plans.', 5),
('c5000000-0000-0000-0000-000000000037', 'A', 'Single random growth hormone level', false, 'Ruled out because growth hormone is secreted in a pulsatile manner throughout the day, making a single random level unreliable for diagnosis; IGF-1 (which is more stable) is the preferred initial screening test.', 1),
('c5000000-0000-0000-0000-000000000037', 'B', 'Serum prolactin level', false, 'Ruled out because although some growth-hormone-secreting tumours co-secrete prolactin, prolactin measurement does not confirm the diagnosis of acromegaly; IGF-1 is the appropriate initial test.', 2),
('c5000000-0000-0000-0000-000000000037', 'C', 'Serum IGF-1 level', true, 'Correct. This is a classic presentation of acromegaly (progressive coarsening of facial features, enlarging hands/feet, jaw growth, new diabetes, and obstructive sleep apnoea/snoring), caused by excess growth hormone, usually from a pituitary adenoma. Serum IGF-1 is the recommended initial screening test, as it reflects integrated growth hormone secretion over time (growth hormone itself is secreted in a pulsatile fashion and is unreliable as a single random measurement).', 3),
('c5000000-0000-0000-0000-000000000037', 'D', '24-hour urinary free cortisol', false, $x$Ruled out because this test screens for Cushing's syndrome (cortisol excess), which does not explain this patient's presentation of coarsened features, macrognathia, and enlarging extremities.$x$, 4),
('c5000000-0000-0000-0000-000000000037', 'E', 'Water deprivation test', false, $x$Ruled out because this test investigates suspected diabetes insipidus, which is not suggested by this patient's presentation.$x$, 5),
('c5000000-0000-0000-0000-000000000038', 'A', 'Migraine with aura; treat with triptans and reassure', false, 'Ruled out because the combination of sudden severe headache with an acute third nerve palsy and known pituitary adenoma is a neurosurgical/endocrine emergency (pituitary apoplexy), not a primary headache disorder; triptans would not address the underlying pathology and delay could be harmful.', 1),
('c5000000-0000-0000-0000-000000000038', 'B', 'Pituitary apoplexy; urgent MRI pituitary, assessment for visual field/acuity loss, and empirical IV hydrocortisone given the risk of acute adrenal insufficiency', true, 'Correct. Sudden severe headache, visual disturbance, and a third cranial nerve palsy (ptosis, dilated pupil, impaired adduction/elevation/depression) in a patient with a known pituitary adenoma is classic for pituitary apoplexy, caused by haemorrhage or infarction of the tumour. This is a neuro-endocrine emergency: urgent imaging is required, and empirical IV hydrocortisone should be given promptly because acute loss of pituitary ACTH secretion can cause life-threatening secondary adrenal insufficiency, even before hormonal results are available.', 2),
('c5000000-0000-0000-0000-000000000038', 'C', 'Subarachnoid haemorrhage; arrange lumbar puncture as the next step', false, 'Ruled out because although sudden severe headache raises subarachnoid haemorrhage as a differential, the specific combination of known pituitary adenoma with a third nerve palsy and visual loss points strongly to pituitary apoplexy, which requires urgent pituitary imaging and hormonal assessment/treatment as the priority, rather than proceeding straight to lumbar puncture.', 3),
('c5000000-0000-0000-0000-000000000038', 'D', 'Cavernous sinus thrombosis; start therapeutic anticoagulation immediately', false, 'Ruled out because although cavernous sinus pathology can cause similar cranial nerve findings, in a patient with a known pituitary adenoma presenting acutely this way, pituitary apoplexy is the much more likely and urgent diagnosis, requiring imaging and steroid cover rather than immediate anticoagulation.', 4),
('c5000000-0000-0000-0000-000000000038', 'E', 'Simple analgesia and outpatient ophthalmology review in two weeks', false, 'Ruled out because this presentation represents a medical emergency (pituitary apoplexy) with risk of permanent visual loss and life-threatening adrenal insufficiency; outpatient deferred review is unsafe.', 5),
('c5000000-0000-0000-0000-000000000039', 'A', 'Levothyroxine should always be started before hydrocortisone to prevent myxoedema coma', false, 'Ruled out because starting thyroid hormone replacement before adequate glucocorticoid cover in a patient with combined deficiencies risks precipitating an adrenal crisis, which is the more immediately dangerous sequence.', 1),
('c5000000-0000-0000-0000-000000000039', 'B', 'The order of hormone replacement does not matter as long as both are eventually started', false, 'Ruled out because the sequence is clinically important: giving levothyroxine first can precipitate a life-threatening adrenal crisis in patients with coexisting untreated secondary adrenal insufficiency.', 2),
('c5000000-0000-0000-0000-000000000039', 'C', 'Sex hormone replacement must be started before either glucocorticoid or thyroid hormone replacement', false, 'Ruled out because sex hormone replacement is not urgent in the same way, and the critical safety principle in panhypopituitarism concerns the glucocorticoid-before-thyroxine sequence to avoid adrenal crisis.', 3),
('c5000000-0000-0000-0000-000000000039', 'D', 'Glucocorticoid (hydrocortisone) replacement must always be started before, or at the same time as, thyroid hormone replacement', true, 'Correct. In panhypopituitarism with combined secondary adrenal insufficiency and secondary hypothyroidism, starting levothyroxine before adequate glucocorticoid replacement can precipitate an adrenal crisis. This is because thyroid hormone increases the metabolic clearance of cortisol and can unmask or worsen an underlying cortisol deficiency; hydrocortisone must therefore be established first (or concurrently).', 4),
('c5000000-0000-0000-0000-000000000039', 'E', 'Growth hormone replacement should be prioritised above all other hormone replacement', false, 'Ruled out because growth hormone replacement is not urgent or life-saving in the same way, and the priority in panhypopituitarism is ensuring adequate glucocorticoid replacement before or alongside thyroid hormone.', 5),
('c5000000-0000-0000-0000-000000000040', 'A', 'Syndrome of inappropriate antidiuretic hormone secretion (SIADH)', false, 'Ruled out because SIADH causes hyponatraemia with concentrated urine due to excess ADH, the opposite biochemical pattern (hypernatraemia with dilute urine) seen in this patient.', 1),
('c5000000-0000-0000-0000-000000000040', 'B', 'Primary polydipsia', false, 'Ruled out because although primary polydipsia also causes dilute polyuria, it is typically associated with normal or low serum sodium (from water excess) rather than hypernatraemia, and there is a clear organic precipitant (head injury) here.', 2),
('c5000000-0000-0000-0000-000000000040', 'C', 'Nephrogenic diabetes insipidus due to lithium toxicity', false, 'Ruled out because there is no history of lithium use here, and the acute onset following traumatic brain injury strongly points to a cranial (central) cause related to the injury itself.', 3),
('c5000000-0000-0000-0000-000000000040', 'D', 'Acute kidney injury with high-output polyuric phase', false, 'Ruled out because this pattern of dilute polyuria with hypernatraemia and appropriately raised plasma osmolality but inappropriately low urine osmolality reflects a specific ADH deficiency (cranial DI), not a nonspecific renal recovery phase.', 4),
('c5000000-0000-0000-0000-000000000040', 'E', 'Cranial diabetes insipidus', true, 'Correct. Polyuria with dilute urine, hypernatraemia, and high plasma osmolality with inappropriately low urine osmolality following traumatic brain injury or pituitary/hypothalamic surgery is characteristic of cranial diabetes insipidus, caused by insufficient antidiuretic hormone (ADH) secretion from a damaged posterior pituitary/hypothalamus, leading to an inability to concentrate urine.', 5),
('c5000000-0000-0000-0000-000000000041', 'A', 'Non-functioning pituitary macroadenoma causing optic chiasm compression', true, 'Correct. Bitemporal hemianopia results from compression of the optic chiasm by a suprasellar mass; in the context of a large pituitary tumour with no evidence of hormone hypersecretion, this represents a non-functioning (non-secreting) pituitary macroadenoma, which typically presents with mass effect symptoms (visual field loss, headache, hypopituitarism) rather than a hormone excess syndrome.', 1),
('c5000000-0000-0000-0000-000000000041', 'B', 'Prolactinoma causing galactorrhoea and amenorrhoea', false, 'Ruled out because there is no evidence of hormone hypersecretion described, and this patient is male with no galactorrhoea; the presentation here is dominated by mass effect (visual field loss) from a non-functioning tumour.', 2),
('c5000000-0000-0000-0000-000000000041', 'C', 'Acromegaly due to growth hormone excess', false, 'Ruled out because there is no mention of the characteristic features of growth hormone excess (coarsened features, enlarging hands/feet), and hormonal screening showed no hypersecretion.', 3),
('c5000000-0000-0000-0000-000000000041', 'D', 'Craniopharyngioma presenting for the first time in childhood', false, $x$Ruled out because craniopharyngiomas classically present in children or young adults, and this patient's age and imaging findings (pituitary mass) fit a pituitary macroadenoma rather than this diagnosis.$x$, 4),
('c5000000-0000-0000-0000-000000000041', 'E', 'Optic neuritis due to multiple sclerosis', false, 'Ruled out because optic neuritis typically causes unilateral visual loss and pain on eye movement, not the bitemporal hemianopia pattern from chiasmal compression seen with a pituitary mass on imaging.', 5),
('c5000000-0000-0000-0000-000000000042', 'A', 'Testosterone replacement therapy as first-line treatment', false, 'Ruled out because testosterone replacement does not address the underlying cause (hyperprolactinaemia suppressing gonadotrophins) and could theoretically stimulate tumour growth in some contexts; treating the prolactinoma with a dopamine agonist is the appropriate first step, which usually restores normal testosterone.', 1),
('c5000000-0000-0000-0000-000000000042', 'B', 'Immediate transsphenoidal surgery', false, 'Ruled out because microprolactinomas, like macroprolactinomas, are managed first-line with dopamine agonists, which are highly effective; surgery is reserved for cases resistant to or intolerant of medical therapy.', 2),
('c5000000-0000-0000-0000-000000000042', 'C', 'Radiotherapy as first-line treatment', false, 'Ruled out because radiotherapy is not first-line for prolactinoma; it is reserved for tumours not controlled by medical therapy or surgery.', 3),
('c5000000-0000-0000-0000-000000000042', 'D', 'Reassurance and no treatment, as microadenomas rarely require intervention', false, 'Ruled out because symptomatic hyperprolactinaemia causing hypogonadism (with associated risks such as reduced bone density and sexual dysfunction) warrants treatment with a dopamine agonist, regardless of the small tumour size.', 4),
('c5000000-0000-0000-0000-000000000042', 'E', 'A dopamine agonist such as cabergoline', true, 'Correct. This is a prolactin-secreting pituitary microadenoma causing hyperprolactinaemia, which suppresses gonadotrophin secretion and leads to secondary hypogonadism (reduced libido, erectile dysfunction, gynaecomastia). As with prolactinomas in women, dopamine agonists are first-line treatment, normalising prolactin, restoring gonadal function, and often shrinking the tumour.', 5),
('c5000000-0000-0000-0000-000000000043', 'A', 'Oral liothyronine (T3) as first-line monotherapy', false, 'Ruled out because levothyroxine (T4) is the standard first-line treatment for hypothyroidism; liothyronine is not routinely used as first-line therapy due to its shorter half-life and greater potential for fluctuating levels.', 1),
('c5000000-0000-0000-0000-000000000043', 'B', 'Carbimazole to reduce thyroid hormone production', false, $x$Ruled out because carbimazole is an antithyroid drug used to treat hyperthyroidism (e.g. Graves' disease), not hypothyroidism; giving it here would worsen her thyroid hormone deficiency.$x$, 2),
('c5000000-0000-0000-0000-000000000043', 'C', 'Radioactive iodine therapy', false, 'Ruled out because radioactive iodine ablates the thyroid gland and is used to treat hyperthyroidism, not hypothyroidism; using it here would worsen, not treat, her condition.', 3),
('c5000000-0000-0000-0000-000000000043', 'D', 'Oral levothyroxine, started at an appropriate dose and titrated according to repeat TSH', true, 'Correct. Raised TSH with low free T4 confirms primary hypothyroidism. Levothyroxine (synthetic T4) replacement is first-line treatment, with the dose titrated based on symptomatic response and repeat TSH measurement (typically after 6-8 weeks) until TSH is within the normal range.', 4),
('c5000000-0000-0000-0000-000000000043', 'E', 'Reassurance only, as her symptoms are most likely due to ageing and require no treatment', false, 'Ruled out because her biochemistry confirms primary hypothyroidism, a treatable condition; symptoms are due to thyroid hormone deficiency, not simply ageing, and levothyroxine replacement is indicated.', 5),
('c5000000-0000-0000-0000-000000000044', 'A', 'Toxic multinodular goitre', false, $x$Ruled out because this typically presents in older patients with a nodular (not diffusely smooth) goitre and does not cause the specific autoimmune eye signs (exophthalmos) seen in Graves' disease.$x$, 1),
('c5000000-0000-0000-0000-000000000044', 'B', $x$Graves' disease$x$, true, $x$Correct. A diffusely enlarged, vascular (bruit-associated) goitre with suppressed TSH, raised free T4, and specific eye signs (exophthalmos/thyroid eye disease) is characteristic of Graves' disease, an autoimmune condition caused by TSH-receptor stimulating antibodies.$x$, 2),
('c5000000-0000-0000-0000-000000000044', 'C', $x$Subacute (de Quervain's) thyroiditis$x$, false, $x$Ruled out because this typically presents with a painful, tender thyroid gland, often following a viral illness, and does not cause exophthalmos; this patient's goitre is described as non-tender with classic Graves' eye signs.$x$, 3),
('c5000000-0000-0000-0000-000000000044', 'D', 'Toxic solitary adenoma', false, 'Ruled out because this presents with a single palpable thyroid nodule causing hyperthyroidism, not a diffusely enlarged gland with bruit and eye signs.', 4),
('c5000000-0000-0000-0000-000000000044', 'E', 'Factitious thyrotoxicosis from excess levothyroxine ingestion', false, $x$Ruled out because this would not cause a goitre with a bruit or the specific autoimmune eye disease (exophthalmos) described, which are specific to Graves' disease.$x$, 5),
('c5000000-0000-0000-0000-000000000045', 'A', 'Reassure and treat only the chest infection, as her thyroid symptoms will settle once the infection resolves', false, 'Ruled out because this presentation meets criteria for thyroid storm, a life-threatening emergency requiring specific urgent multi-modal treatment, not management of the infection alone.', 1),
('c5000000-0000-0000-0000-000000000045', 'B', 'Start levothyroxine to help stabilise her thyroid function', false, 'Ruled out because she has severe hyperthyroidism (thyroid storm), not hypothyroidism; giving levothyroxine would worsen her condition.', 2),
('c5000000-0000-0000-0000-000000000045', 'C', 'Urgent supportive care with IV fluids and cooling, plus antithyroid drug therapy, beta-blockade, and IV hydrocortisone, ideally in a high-dependency/intensive care setting', true, 'Correct. This presentation (severe hyperthyroidism, hyperpyrexia, marked tachycardia/new arrhythmia, agitation/confusion, and organ dysfunction, precipitated by infection and non-adherence to antithyroid medication) is thyroid storm, a life-threatening emergency. Management requires urgent supportive care (fluids, active cooling, treatment of the precipitant), high-dose antithyroid drug (e.g. propylthiouracil or carbimazole), a beta-blocker (e.g. propranolol) to control adrenergic symptoms, and corticosteroids (which also reduce peripheral T4-to-T3 conversion), usually in a monitored high-dependency setting given the risk of cardiovascular collapse.', 3),
('c5000000-0000-0000-0000-000000000045', 'D', 'Immediate radioactive iodine therapy', false, 'Ruled out because radioactive iodine is not appropriate in the acute emergency setting of thyroid storm; it is a longer-term definitive treatment option once the patient is stabilised, not an immediate emergency intervention.', 4),
('c5000000-0000-0000-0000-000000000045', 'E', 'Emergency thyroidectomy within the next hour', false, 'Ruled out because surgery is not the immediate management of thyroid storm; the priority is urgent medical stabilisation (antithyroid drugs, beta-blockade, steroids, supportive care) before any consideration of definitive surgical treatment later.', 5),
('c5000000-0000-0000-0000-000000000046', 'A', 'IV levothyroxine (and/or liothyronine) with IV hydrocortisone, gradual rewarming, and intensive supportive care in a monitored setting', true, 'Correct. This presentation (hypothermia, bradycardia, reduced consciousness, and severe biochemical hypothyroidism in a patient who has stopped thyroid hormone replacement) is myxoedema coma, a rare but life-threatening emergency with high mortality. Management requires urgent IV thyroid hormone replacement, IV hydrocortisone (to cover possible coexisting adrenal insufficiency, since thyroid hormone replacement can otherwise precipitate an adrenal crisis), gradual rewarming, and intensive supportive care (often in ICU/HDU) with cardiac monitoring.', 1),
('c5000000-0000-0000-0000-000000000046', 'B', 'Rapid active external rewarming alone, without thyroid hormone replacement', false, 'Ruled out because rewarming alone does not address the underlying severe hypothyroidism driving this presentation; specific thyroid hormone replacement is essential, and rapid rewarming risks vasodilation and cardiovascular collapse in this context.', 2),
('c5000000-0000-0000-0000-000000000046', 'C', 'Oral levothyroxine at her previous outpatient dose, with outpatient follow-up in two weeks', false, 'Ruled out because myxoedema coma is a medical emergency requiring urgent IV (not oral) thyroid hormone replacement and inpatient intensive supportive care, not deferred outpatient management.', 3),
('c5000000-0000-0000-0000-000000000046', 'D', 'IV hydrocortisone alone, withholding thyroid hormone replacement until she is haemodynamically stable', false, 'Ruled out because thyroid hormone replacement is a core, urgent part of treating myxoedema coma and should not be withheld; hydrocortisone is given alongside (not instead of) thyroid hormone to prevent unmasking adrenal insufficiency.', 4),
('c5000000-0000-0000-0000-000000000046', 'E', 'Diuretics to manage suspected fluid overload as the priority intervention', false, 'Ruled out because this does not address the underlying life-threatening hypothyroidism; the priority is urgent thyroid hormone replacement and supportive care, not diuretic therapy.', 5),
('c5000000-0000-0000-0000-000000000047', 'A', 'No treatment is needed as she is asymptomatic and her free T4 is normal', false, 'Ruled out because pregnancy-specific TSH thresholds are lower than in the non-pregnant population, and even subclinical hypothyroidism in pregnancy is generally treated due to fetal and pregnancy risks, regardless of maternal symptoms.', 1),
('c5000000-0000-0000-0000-000000000047', 'B', 'Start carbimazole to normalise her thyroid function', false, 'Ruled out because carbimazole is an antithyroid drug used for hyperthyroidism; this patient has hypothyroidism (raised TSH), so carbimazole would be inappropriate and harmful.', 2),
('c5000000-0000-0000-0000-000000000047', 'C', 'Repeat thyroid function tests in the third trimester only, with no interim action', false, 'Ruled out because untreated thyroid dysfunction throughout pregnancy, particularly in the first trimester when fetal neurodevelopment is highly dependent on maternal thyroid hormone, is associated with adverse outcomes; treatment should not be deferred to a later trimester.', 3),
('c5000000-0000-0000-0000-000000000047', 'D', 'Start levothyroxine replacement, given the specific risks of untreated even mild thyroid dysfunction in pregnancy', true, 'Correct. Thyroid hormone requirements increase in pregnancy, and even subclinical hypothyroidism (mildly raised TSH with normal free T4) is treated with levothyroxine during pregnancy, given the importance of adequate maternal thyroid hormone for fetal neurodevelopment and the association of untreated thyroid dysfunction with adverse pregnancy outcomes (e.g. miscarriage, preterm birth).', 4),
('c5000000-0000-0000-0000-000000000047', 'E', 'Advise increased dietary iodine intake as the sole intervention', false, 'Ruled out because there is no indication of iodine deficiency here, and dietary iodine advice alone does not adequately address confirmed subclinical hypothyroidism in pregnancy; thyroid hormone replacement is required.', 5),
('c5000000-0000-0000-0000-000000000048', 'A', 'Watchful waiting with repeat ultrasound in twelve months, as papillary carcinoma rarely requires treatment', false, 'Ruled out because although papillary thyroid carcinoma generally has an excellent prognosis, a confirmed diagnosis on FNA cytology requires active surgical management, not observation alone.', 1),
('c5000000-0000-0000-0000-000000000048', 'B', 'External beam radiotherapy alone, without surgery', false, 'Ruled out because surgical resection is the primary treatment for papillary thyroid carcinoma; radiotherapy (specifically radioactive iodine) is used as an adjunct after surgery, not as sole primary treatment.', 2),
('c5000000-0000-0000-0000-000000000048', 'C', 'Chemotherapy as first-line treatment', false, 'Ruled out because differentiated thyroid cancers such as papillary carcinoma are not typically treated with chemotherapy as first-line therapy; surgery followed by radioactive iodine is standard.', 3),
('c5000000-0000-0000-0000-000000000048', 'D', 'Antithyroid medication (carbimazole) to shrink the nodule', false, 'Ruled out because carbimazole treats hyperthyroidism due to excess thyroid hormone production; it has no role in treating a malignant thyroid nodule with normal thyroid function.', 4),
('c5000000-0000-0000-0000-000000000048', 'E', 'Referral for surgical resection (thyroidectomy), followed by consideration of radioactive iodine ablation and long-term TSH suppression with levothyroxine', true, 'Correct. Papillary thyroid carcinoma, the most common type of thyroid cancer, is generally managed with surgical resection (total or near-total thyroidectomy, sometimes with neck dissection depending on staging), often followed by radioactive iodine ablation of residual thyroid tissue and lifelong levothyroxine replacement, with TSH suppression as part of ongoing management to reduce recurrence risk.', 5),
('c5000000-0000-0000-0000-000000000049', 'A', $x$Graves' disease unrelated to his medication$x$, false, $x$Ruled out because although Graves' disease is a cause of thyrotoxicosis, the temporal relationship with amiodarone use and the well-recognised association between amiodarone and thyroid dysfunction make amiodarone-induced thyrotoxicosis the most likely explanation to consider first.$x$, 1),
('c5000000-0000-0000-0000-000000000049', 'B', 'Amiodarone-induced thyrotoxicosis', true, 'Correct. Amiodarone has a very high iodine content and can cause either hypothyroidism or thyrotoxicosis (amiodarone-induced thyrotoxicosis, via an iodine-induced excess in susceptible thyroid tissue or a destructive thyroiditis). New hyperthyroid symptoms (weight loss, palpitations, heat intolerance) with suppressed TSH and raised free T4 in a patient on amiodarone is most likely amiodarone-induced thyrotoxicosis.', 2),
('c5000000-0000-0000-0000-000000000049', 'C', 'Subacute thyroiditis due to a recent viral illness', false, 'Ruled out because there is no history of a preceding viral illness or thyroid tenderness described, and the strong association with amiodarone use makes drug-induced thyroid dysfunction the most likely cause.', 3),
('c5000000-0000-0000-0000-000000000049', 'D', 'Factitious thyrotoxicosis from covert levothyroxine use', false, 'Ruled out because there is no history suggesting surreptitious levothyroxine use, and amiodarone is a well-recognised and much more likely cause of new thyroid dysfunction in this context.', 4),
('c5000000-0000-0000-0000-000000000049', 'E', 'Toxic multinodular goitre coincidentally presenting at the same time', false, 'Ruled out because while possible in principle, the well-documented and common association between amiodarone therapy and thyroid dysfunction makes amiodarone-induced thyrotoxicosis the most likely explanation to investigate first.', 5),
('c5000000-0000-0000-0000-000000000050', 'A', $x$Graves' disease newly presenting after pregnancy$x$, false, $x$Ruled out because Graves' disease typically causes a persistent, ongoing thyrotoxicosis rather than the classic biphasic (thyrotoxic then hypothyroid) pattern seen here, which is characteristic of postpartum thyroiditis.$x$, 1),
('c5000000-0000-0000-0000-000000000050', 'B', $x$Subacute (de Quervain's) thyroiditis unrelated to pregnancy$x$, false, $x$Ruled out because subacute thyroiditis classically presents with a painful, tender thyroid gland (often after a viral illness), whereas this patient's gland is non-tender and the timing is specifically postpartum, pointing to postpartum thyroiditis instead.$x$, 2),
('c5000000-0000-0000-0000-000000000050', 'C', 'Postpartum thyroiditis', true, 'Correct. Postpartum thyroiditis is an autoimmune-mediated inflammatory thyroid condition occurring in the months following delivery, classically causing a transient thyrotoxic phase (from the release of preformed thyroid hormone due to gland inflammation) followed by a hypothyroid phase, with a painless, non-tender goitre; most women eventually return to euthyroid status, although some develop permanent hypothyroidism.', 3),
('c5000000-0000-0000-0000-000000000050', 'D', 'Toxic multinodular goitre', false, 'Ruled out because this typically occurs in older patients with a nodular goitre and causes persistent hyperthyroidism, not the biphasic thyrotoxic-then-hypothyroid pattern seen in this postpartum patient.', 4),
('c5000000-0000-0000-0000-000000000050', 'E', $x$Sheehan's syndrome (postpartum pituitary infarction)$x$, false, $x$Ruled out because Sheehan's syndrome causes hypopituitarism (typically following severe postpartum haemorrhage), which would present with low TSH/other pituitary hormone deficiencies, not the primary thyroid gland thyrotoxic-then-hypothyroid pattern with a goitre described here.$x$, 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c5000000-0000-0000-0000-000000000001', 'Addisonian crisis presents with hypotension/shock, hyponatraemia, hyperkalaemia and hypoglycaemia, precipitated by illness, vomiting, surgery or missed medication.', 1),
('c5000000-0000-0000-0000-000000000001', 'Treatment (IV hydrocortisone 100 mg plus IV 0.9% saline) is started immediately on clinical suspicion; do not delay for a synacthen test.', 2),
('c5000000-0000-0000-0000-000000000001', $x$Patients with adrenal insufficiency need 'sick day rules' education to prevent crises during intercurrent illness.$x$, 3),
('c5000000-0000-0000-0000-000000000002', $x$Primary adrenal insufficiency (Addison's) causes hyperpigmentation because low cortisol removes negative feedback, raising ACTH/POMC, which stimulates melanocytes; secondary (pituitary) causes do not cause pigmentation.$x$, 1),
('c5000000-0000-0000-0000-000000000002', 'The short synacthen test with paired ACTH both confirms adrenal insufficiency and localises it as primary (high ACTH) or secondary (low/normal ACTH).', 2),
('c5000000-0000-0000-0000-000000000002', 'Hyponatraemia with hyperkalaemia reflects aldosterone deficiency and occurs only in primary adrenal failure, not secondary (pituitary-driven) adrenal insufficiency, since aldosterone secretion is largely renin-driven and independent of ACTH.', 3),
('c5000000-0000-0000-0000-000000000003', 'All patients on chronic glucocorticoid replacement for adrenal insufficiency should carry a steroid card and understand sick day rules: double the oral dose during intercurrent illness/fever.', 1),
('c5000000-0000-0000-0000-000000000003', 'Vomiting, diarrhoea, or inability to tolerate oral medication in a steroid-dependent patient is an indication for emergency parenteral hydrocortisone, not oral dose adjustment alone.', 2),
('c5000000-0000-0000-0000-000000000003', 'Patients should also be given IM hydrocortisone to use at home (and taught how to self-administer it) as a bridge to emergency care if vomiting prevents oral dosing.', 3),
('c5000000-0000-0000-0000-000000000004', 'Any glucocorticoid course longer than around 3-4 weeks (or shorter courses in patients with other risk factors) should be tapered rather than stopped abruptly to avoid adrenal crisis from HPA axis suppression.', 1),
('c5000000-0000-0000-0000-000000000004', $x$Iatrogenic Cushing's syndrome from exogenous steroids is the most common cause of Cushing's syndrome overall and presents identically to endogenous cortisol excess.$x$, 2),
('c5000000-0000-0000-0000-000000000004', 'Patients on long-term steroids should carry a steroid treatment card and receive sick day rule counselling in case of intercurrent illness or surgery.', 3),
('c5000000-0000-0000-0000-000000000005', 'Primary hyperaldosteronism should be suspected in resistant hypertension with hypokalaemia; the screening test is the aldosterone:renin ratio (raised aldosterone, suppressed renin).', 1),
('c5000000-0000-0000-0000-000000000005', 'Secondary hyperaldosteronism (e.g. renal artery stenosis, heart failure) shows both raised renin and raised aldosterone, distinguishing it from the primary form.', 2),
('c5000000-0000-0000-0000-000000000005', 'Confirmed cases are further investigated with adrenal CT/venous sampling to distinguish a unilateral adenoma (surgical) from bilateral hyperplasia (managed medically with a mineralocorticoid receptor antagonist such as spironolactone).', 3),
('c5000000-0000-0000-0000-000000000006', 'Preoperative management of phaeochromocytoma requires alpha-blockade first (to control catecholamine-driven vasoconstriction), followed by beta-blockade if needed for reflex tachycardia; never beta-block first.', 1),
('c5000000-0000-0000-0000-000000000006', 'Diagnosis is confirmed biochemically with plasma free metanephrines or 24-hour urinary metanephrines before proceeding to imaging (CT/MRI abdomen) for localisation.', 2),
('c5000000-0000-0000-0000-000000000006', 'Adequate alpha-blockade also allows compensatory volume expansion, reducing the risk of severe hypotension when the tumour is removed intraoperatively.', 3),
('c5000000-0000-0000-0000-000000000007', 'Long-term exogenous steroid use is the most common cause of secondary adrenal insufficiency, via HPA axis suppression from negative feedback.', 1),
('c5000000-0000-0000-0000-000000000007', 'Plasma ACTH distinguishes primary (raised ACTH, adrenal-level failure) from secondary (low/inappropriately normal ACTH, pituitary/hypothalamic-level failure) adrenal insufficiency.', 2),
('c5000000-0000-0000-0000-000000000007', 'Patients on long-term steroids need higher (stress) doses during acute illness or surgery because their HPA axis cannot mount an appropriate endogenous cortisol response.', 3),
('c5000000-0000-0000-0000-000000000008', 'Primary hyperparathyroidism is characterised by raised calcium, low phosphate, and a PTH that is raised or inappropriately normal (not suppressed).', 1),
('c5000000-0000-0000-0000-000000000008', $x$'Bones, stones, abdominal groans, and psychic moans' summarises the classic features: bone pain, renal stones, GI symptoms (constipation, pain), and neuropsychiatric symptoms.$x$, 2),
('c5000000-0000-0000-0000-000000000008', 'Malignancy-related hypercalcaemia and vitamin D excess both suppress PTH via negative feedback, which helps distinguish them from primary hyperparathyroidism.', 3),
('c5000000-0000-0000-0000-000000000009', 'Osteoporosis is defined as a DEXA T-score of -2.5 or below; a fragility fracture in this context confirms the diagnosis and mandates treatment.', 1),
('c5000000-0000-0000-0000-000000000009', 'Oral bisphosphonates (e.g. alendronic acid, risedronate) are first-line therapy, alongside correction of calcium/vitamin D deficiency.', 2),
('c5000000-0000-0000-0000-000000000009', 'FRAX or similar fracture risk tools are used to guide treatment decisions, particularly in patients without an existing fragility fracture.', 3),
('c5000000-0000-0000-0000-000000000010', 'Osteomalacia results from vitamin D deficiency causing impaired mineralisation of bone matrix; risk factors include reduced sun exposure, dark skin, malabsorption, and dietary insufficiency.', 1),
('c5000000-0000-0000-0000-000000000010', 'Typical biochemistry is low/low-normal calcium and phosphate with raised ALP and low vitamin D, distinguishing it from osteoporosis (normal biochemistry) and primary hyperparathyroidism (raised calcium).', 2),
('c5000000-0000-0000-0000-000000000010', 'Treatment is vitamin D (colecalciferol) replacement, with calcium supplementation if intake is inadequate.', 3),
('c5000000-0000-0000-0000-000000000011', 'Severe hypercalcaemia (typically >3.5 mmol/L) or symptomatic hypercalcaemia is a medical emergency requiring urgent IV fluid rehydration followed by an IV bisphosphonate.', 1),
('c5000000-0000-0000-0000-000000000011', 'Malignancy is the most common cause of severe hypercalcaemia in hospital inpatients; humoral hypercalcaemia (PTHrP) and bone metastases are common mechanisms.', 2),
('c5000000-0000-0000-0000-000000000011', 'ECG changes of hypercalcaemia include a shortened QT interval; severe hypercalcaemia can also cause arrhythmias.', 3),
('c5000000-0000-0000-0000-000000000012', 'Hypocalcaemia is a recognised early complication of thyroid or parathyroid surgery due to inadvertent damage or devascularisation of the parathyroid glands.', 1),
('c5000000-0000-0000-0000-000000000012', $x$Chvostek's sign (facial twitching on tapping the facial nerve) and Trousseau's sign (carpal spasm on cuff inflation) indicate neuromuscular irritability from hypocalcaemia.$x$, 2),
('c5000000-0000-0000-0000-000000000012', 'Symptomatic or severe hypocalcaemia requires IV calcium gluconate; mild, asymptomatic cases may be managed with oral calcium and vitamin D/alfacalcidol.', 3),
('c5000000-0000-0000-0000-000000000013', $x$Paget's disease of bone classically presents with an isolated raised ALP, normal calcium and phosphate, and localised bone pain/deformity, most often affecting the pelvis, femur, skull, and tibia.$x$, 1),
('c5000000-0000-0000-0000-000000000013', 'Radiographic features include cortical thickening, bone enlargement/deformity (e.g. bowing), and a mixed lytic/sclerotic pattern.', 2),
('c5000000-0000-0000-0000-000000000013', $x$Bisphosphonates are the treatment of choice for symptomatic Paget's disease to reduce excessive bone turnover.$x$, 3),
('c5000000-0000-0000-0000-000000000014', 'Long-term glucocorticoid use is a major, independent risk factor for osteoporosis and fragility fracture, and should prompt proactive fracture risk assessment rather than waiting for a fracture.', 1),
('c5000000-0000-0000-0000-000000000014', 'Bone-protective therapy (typically a bisphosphonate, alongside calcium/vitamin D) is often started prophylactically in patients starting or continuing long-term steroids, guided by age, dose, and fracture risk tools.', 2),
('c5000000-0000-0000-0000-000000000014', 'The underlying condition requiring steroids (e.g. giant cell arteritis, where steroids prevent blindness) must still be treated adequately; steroid dose should not be reduced or stopped purely for bone health reasons.', 3),
('c5000000-0000-0000-0000-000000000015', 'Type 2 diabetes is diagnosed with a fasting plasma glucose >=7.0 mmol/L or HbA1c >=48 mmol/mol on two occasions in an asymptomatic patient (one occasion is sufficient if symptomatic).', 1),
('c5000000-0000-0000-0000-000000000015', 'Metformin alongside lifestyle modification is first-line management for type 2 diabetes unless contraindicated (e.g. significant renal impairment) or not tolerated.', 2),
('c5000000-0000-0000-0000-000000000015', 'Metformin does not cause hypoglycaemia when used alone, as it works by reducing hepatic gluconeogenesis and improving insulin sensitivity rather than stimulating insulin secretion.', 3),
('c5000000-0000-0000-0000-000000000016', 'In symptomatic patients, a single abnormal result (random glucose >=11.1 mmol/L, fasting glucose >=7.0 mmol/L, or HbA1c >=48 mmol/mol) is diagnostic of diabetes; asymptomatic patients need two abnormal results.', 1),
('c5000000-0000-0000-0000-000000000016', 'HbA1c should not be used for diagnosis in certain situations, e.g. suspected type 1 diabetes, pregnancy, recent onset of symptoms (<2-3 months), or conditions affecting red cell turnover.', 2),
('c5000000-0000-0000-0000-000000000016', 'Classic hyperglycaemic symptoms are polyuria, polydipsia, unexplained weight loss, and fatigue.', 3),
('c5000000-0000-0000-0000-000000000017', 'Type 1 diabetes classically presents in younger, often lean patients with an acute onset of osmotic symptoms, weight loss, and a tendency towards ketosis due to absolute insulin deficiency.', 1),
('c5000000-0000-0000-0000-000000000017', 'All newly diagnosed patients with suspected type 1 diabetes require prompt insulin initiation; delay risks progression to diabetic ketoacidosis.', 2),
('c5000000-0000-0000-0000-000000000017', 'Autoantibody testing (e.g. anti-GAD, islet cell antibodies) and C-peptide can help confirm type 1 diabetes when the clinical picture is unclear.', 3),
('c5000000-0000-0000-0000-000000000018', 'Metformin is contraindicated or requires dose reduction/cessation in significant renal impairment because it is renally cleared and accumulation increases the risk of lactic acidosis.', 1),
('c5000000-0000-0000-0000-000000000018', 'eGFR should be monitored regularly in diabetic patients on metformin; dose review is typically triggered around eGFR 45, with cessation typically advised around eGFR 30 mL/min/1.73m^2 or below (local guidance may vary slightly).', 2),
('c5000000-0000-0000-0000-000000000018', 'Diabetic nephropathy is a leading cause of progressive CKD in type 2 diabetes and requires monitoring of renal function alongside review of nephrotoxic/renally-cleared medications.', 3),
('c5000000-0000-0000-0000-000000000019', 'Annual diabetic foot screening assesses pulses, sensation (10g monofilament, vibration), and skin integrity to stratify patients into low, moderate, or high risk categories for foot complications.', 1),
('c5000000-0000-0000-0000-000000000019', 'Loss of protective sensation from peripheral neuropathy is a major independent risk factor for unnoticed trauma and subsequent ulceration, even when pulses are normal.', 2),
('c5000000-0000-0000-0000-000000000019', 'Patients at moderate/high risk require more frequent podiatry review, foot care education, and appropriate footwear advice to prevent ulceration.', 3),
('c5000000-0000-0000-0000-000000000020', 'Gestational diabetes is diagnosed using a 75g OGTT with specific pregnancy thresholds (fasting >=5.6 mmol/L and/or 2-hour >=7.8 mmol/L).', 1),
('c5000000-0000-0000-0000-000000000020', 'First-line management is dietary and lifestyle modification with blood glucose self-monitoring; pharmacological treatment (metformin and/or insulin) is added if targets are not met.', 2),
('c5000000-0000-0000-0000-000000000020', 'Poorly controlled gestational diabetes increases risk of fetal macrosomia, shoulder dystocia, and neonatal hypoglycaemia, so tight glycaemic control and monitoring are important throughout pregnancy.', 3),
('c5000000-0000-0000-0000-000000000021', 'Background (non-proliferative) diabetic retinopathy features microaneurysms, dot/blot haemorrhages, and hard exudates, without neovascularisation.', 1),
('c5000000-0000-0000-0000-000000000021', 'Proliferative retinopathy (neovascularisation), pre-proliferative changes, or maculopathy/macular oedema warrant more urgent ophthalmology referral due to sight-threatening potential.', 2),
('c5000000-0000-0000-0000-000000000021', 'All patients with diabetes require regular (typically annual) retinal screening regardless of symptoms, as retinopathy is often asymptomatic until advanced.', 3),
('c5000000-0000-0000-0000-000000000022', 'DKA is defined by the triad of hyperglycaemia, ketosis (raised blood or urine ketones), and metabolic acidosis (pH <7.3 or bicarbonate <15 mmol/L).', 1),
('c5000000-0000-0000-0000-000000000022', 'Management is IV fluid resuscitation first, followed by a fixed-rate IV insulin infusion; potassium must be monitored closely and replaced as needed once insulin therapy begins.', 2),
('c5000000-0000-0000-0000-000000000022', 'Common precipitants of DKA include infection, missed or reduced insulin doses (including during intercurrent illness), and new diagnosis of type 1 diabetes.', 3),
('c5000000-0000-0000-0000-000000000023', 'HHS occurs in type 2 diabetes with severe hyperglycaemia, profound dehydration, and markedly raised serum osmolality, typically WITHOUT significant ketosis or acidosis (distinguishing it from DKA).', 1),
('c5000000-0000-0000-0000-000000000023', 'HHS develops more gradually (days) than DKA and predominantly affects older patients with type 2 diabetes, often precipitated by infection, dehydration, or non-compliance.', 2),
('c5000000-0000-0000-0000-000000000023', 'Management centres on slow, careful IV fluid rehydration (as rapid correction risks central pontine myelinolysis/cerebral oedema), with cautious insulin use only if glucose is not falling with fluids alone, plus VTE prophylaxis given the very high thrombotic risk.', 3),
('c5000000-0000-0000-0000-000000000024', 'In severe hypoglycaemia with reduced consciousness or unsafe swallow, oral treatment is contraindicated; IM glucagon or IV glucose (10-20%) are used instead.', 1),
('c5000000-0000-0000-0000-000000000024', 'Glucagon mobilises hepatic glycogen and may be less effective in patients with depleted glycogen stores (e.g. alcohol excess, malnutrition); IV glucose is preferred when IV access is readily available.', 2),
('c5000000-0000-0000-0000-000000000024', 'After initial treatment, patients need reassessment and often a longer-acting carbohydrate once able to swallow safely, as hypoglycaemia can recur (especially after glucagon, whose effect is transient).', 3),
('c5000000-0000-0000-0000-000000000025', 'Insulin therapy in DKA drives potassium intracellularly, commonly causing a significant fall in serum potassium regardless of the admission level; regular (hourly initially) monitoring is essential.', 1),
('c5000000-0000-0000-0000-000000000025', 'Potassium replacement is added to IV fluids according to protocol once levels fall towards or below the normal range, to prevent life-threatening hypokalaemia and cardiac arrhythmia.', 2),
('c5000000-0000-0000-0000-000000000025', 'If potassium is very low, some protocols recommend caution or temporary reduction of the insulin rate; but stopping insulin outright is not the standard response to modest hypokalaemia within an established DKA regimen.', 3),
('c5000000-0000-0000-0000-000000000026', 'Mild-to-moderate hypoglycaemia in a conscious patient able to swallow safely is treated with 15-20g of fast-acting oral carbohydrate, followed by a recheck at 15 minutes and repeat treatment if still low.', 1),
('c5000000-0000-0000-0000-000000000026', 'Once treated, a longer-acting starchy carbohydrate snack helps prevent recurrence, particularly before further activity.', 2),
('c5000000-0000-0000-0000-000000000026', 'Patients with diabetes must not drive during or immediately after hypoglycaemia; DVLA rules require blood glucose to be checked and safely above the relevant threshold before driving resumes.', 3),
('c5000000-0000-0000-0000-000000000027', $x$'Sick day rules' for type 1 diabetes: never stop insulin, monitor glucose and ketones more frequently, maintain hydration, and adjust (often increase) insulin doses according to readings.$x$, 1),
('c5000000-0000-0000-0000-000000000027', 'Illness raises insulin requirements via counter-regulatory stress hormones (cortisol, catecholamines, glucagon), even if oral intake is reduced.', 2),
('c5000000-0000-0000-0000-000000000027', 'Failure to continue insulin during illness in type 1 diabetes is a recognised and preventable precipitant of DKA.', 3),
('c5000000-0000-0000-0000-000000000028', 'DKA nearly always has an identifiable precipitant (infection, missed/inadequate insulin, illness, new diagnosis, or occasionally other acute illness); this must be actively sought and treated.', 1),
('c5000000-0000-0000-0000-000000000028', 'Standard DKA management (IV fluids, fixed-rate insulin, potassium monitoring/replacement) must run in parallel with, not instead of, treatment of the precipitating cause.', 2),
('c5000000-0000-0000-0000-000000000028', 'Even when insulin doses have been continued as normal, illness/infection can still precipitate DKA due to increased insulin requirements during physiological stress.', 3),
('c5000000-0000-0000-0000-000000000029', 'Familial hypercholesterolaemia should be suspected with markedly elevated LDL cholesterol, tendon xanthomata, corneal arcus, and a family history of premature cardiovascular disease.', 1),
('c5000000-0000-0000-0000-000000000029', 'Diagnostic clinical criteria (e.g. Simon Broome criteria) combine cholesterol levels, clinical signs, family history, and (where available) genetic testing.', 2),
('c5000000-0000-0000-0000-000000000029', 'First-degree relatives of an index case should be offered cascade testing, as early identification and statin treatment substantially reduce cardiovascular risk.', 3),
('c5000000-0000-0000-0000-000000000030', 'A QRISK score (or equivalent validated tool) of 10% or higher over 10 years is the threshold for offering statin therapy for primary prevention of cardiovascular disease.', 1),
('c5000000-0000-0000-0000-000000000030', 'Atorvastatin 20 mg is the standard first-line statin dose for primary prevention; higher doses (e.g. 80 mg) are used for secondary prevention.', 2),
('c5000000-0000-0000-0000-000000000030', 'Lifestyle advice (diet, exercise, smoking cessation) should be offered alongside, not instead of, statin therapy when risk thresholds are met.', 3),
('c5000000-0000-0000-0000-000000000031', 'Statin-induced myopathy ranges from mild myalgia to severe myopathy and rhabdomyolysis; significant symptoms with markedly raised CK warrant stopping the statin.', 1),
('c5000000-0000-0000-0000-000000000031', 'Rhabdomyolysis can cause acute kidney injury from myoglobin-induced renal tubular damage, so renal function should be monitored alongside CK.', 2),
('c5000000-0000-0000-0000-000000000031', 'After resolution, alternative strategies include a lower statin dose, a different statin, alternate-day dosing, or a non-statin lipid-lowering agent, guided by ongoing cardiovascular risk.', 3),
('c5000000-0000-0000-0000-000000000032', 'High-intensity statin therapy (e.g. atorvastatin 80 mg) is recommended for secondary prevention after an acute coronary syndrome, irrespective of baseline cholesterol.', 1),
('c5000000-0000-0000-0000-000000000032', 'This differs from primary prevention, where a lower starting dose (e.g. atorvastatin 20 mg) is typically used based on estimated cardiovascular risk.', 2),
('c5000000-0000-0000-0000-000000000032', 'Lipid profile is rechecked after starting treatment to assess response, but the decision to start high-intensity therapy after an acute event should not wait for repeat lipid results.', 3),
('c5000000-0000-0000-0000-000000000033', 'Macrolide antibiotics (clarithromycin, erythromycin) are potent CYP3A4 inhibitors and significantly increase levels of CYP3A4-metabolised statins (simvastatin, atorvastatin), raising myopathy/rhabdomyolysis risk.', 1),
('c5000000-0000-0000-0000-000000000033', 'Current guidance recommends temporarily withholding an interacting statin during a course of an interacting macrolide, or choosing an alternative antibiotic or a statin not metabolised by CYP3A4 (e.g. pravastatin, rosuvastatin) where appropriate.', 2),
('c5000000-0000-0000-0000-000000000033', 'Checking for drug interactions before prescribing new antibiotics in patients on regular statins is an important prescribing safety check for any doctor.', 3),
('c5000000-0000-0000-0000-000000000034', 'Severe hypertriglyceridaemia (very high levels, e.g. above roughly 11.3 mmol/L) is one of the recognised causes of acute pancreatitis, alongside gallstones and alcohol (which together with hypertriglyceridaemia account for the large majority of cases).', 1),
('c5000000-0000-0000-0000-000000000034', 'Poorly controlled diabetes and alcohol excess can both independently raise triglyceride levels and may coexist with, or precipitate, severe hypertriglyceridaemia-induced pancreatitis.', 2),
('c5000000-0000-0000-0000-000000000034', 'Management of hypertriglyceridaemia-induced pancreatitis includes standard supportive pancreatitis care plus specific triglyceride-lowering measures (e.g. fasting, insulin infusion in diabetic patients, fibrates once stable) to reduce recurrence risk.', 3),
('c5000000-0000-0000-0000-000000000035', 'Familial hypercholesterolaemia is autosomal dominant; first-degree relatives of an index case have a 50% risk of inheriting the condition.', 1),
('c5000000-0000-0000-0000-000000000035', 'Cascade testing systematically tests relatives of confirmed cases (starting with first-degree relatives) to identify others affected, enabling early treatment and reduced cardiovascular risk.', 2),
('c5000000-0000-0000-0000-000000000035', 'Early identification and statin treatment in affected relatives, even before symptoms develop, substantially reduces their lifetime risk of premature cardiovascular disease.', 3),
('c5000000-0000-0000-0000-000000000036', 'Prolactinomas are the most common functioning pituitary adenoma and classically cause galactorrhoea and amenorrhoea/oligomenorrhoea in women, or reduced libido/erectile dysfunction in men.', 1),
('c5000000-0000-0000-0000-000000000036', 'Dopamine agonists (cabergoline, bromocriptine) are first-line treatment for prolactinoma, effectively lowering prolactin and often shrinking the tumour, unlike most other pituitary adenomas which are primarily managed surgically.', 2),
('c5000000-0000-0000-0000-000000000036', 'Other causes of hyperprolactinaemia (pregnancy, certain antipsychotic/antiemetic drugs, hypothyroidism, renal failure) should be excluded before attributing hyperprolactinaemia to a prolactinoma.', 3),
('c5000000-0000-0000-0000-000000000037', 'Acromegaly results from excess growth hormone (usually from a pituitary adenoma) and presents with gradual coarsening of facial features, enlarging hands/feet, jaw growth, sleep apnoea, and metabolic complications including diabetes.', 1),
('c5000000-0000-0000-0000-000000000037', 'Serum IGF-1 is the preferred initial screening test because growth hormone secretion is pulsatile; a raised IGF-1 is followed by an oral glucose tolerance test with growth hormone measurement to confirm the diagnosis (failure of GH suppression).', 2),
('c5000000-0000-0000-0000-000000000037', 'Untreated acromegaly increases cardiovascular, respiratory (sleep apnoea), and metabolic (diabetes) morbidity, so timely diagnosis and treatment (surgery, medical therapy, or radiotherapy) are important.', 3),
('c5000000-0000-0000-0000-000000000038', 'Pituitary apoplexy presents with sudden severe headache, visual field/acuity loss, and ophthalmoplegia (often third nerve palsy) due to haemorrhage or infarction within a pituitary tumour.', 1),
('c5000000-0000-0000-0000-000000000038', 'Empirical IV hydrocortisone should be given promptly in suspected apoplexy because of the risk of acute secondary adrenal insufficiency from sudden loss of ACTH secretion, without waiting for confirmatory hormone results.', 2),
('c5000000-0000-0000-0000-000000000038', 'Urgent MRI pituitary and neurosurgical/endocrine assessment are required; some patients need urgent surgical decompression, particularly with severe or progressive visual loss.', 3),
('c5000000-0000-0000-0000-000000000039', 'In panhypopituitarism with combined secondary adrenal insufficiency and secondary hypothyroidism, glucocorticoid replacement must be started before or with thyroid hormone replacement, never after.', 1),
('c5000000-0000-0000-0000-000000000039', 'Thyroid hormone increases cortisol metabolism/clearance; starting it first in an unreplaced cortisol-deficient patient can precipitate an adrenal crisis.', 2),
('c5000000-0000-0000-0000-000000000039', 'This principle mirrors the general rule that unrecognised adrenal insufficiency must always be considered and treated before or alongside thyroid hormone replacement in any patient with suspected combined pituitary hormone deficiency.', 3),
('c5000000-0000-0000-0000-000000000040', 'Cranial diabetes insipidus results from insufficient ADH secretion (often due to head injury, pituitary surgery, or hypothalamic pathology), causing large volumes of dilute urine and a tendency towards hypernatraemia if fluid intake cannot keep pace.', 1),
('c5000000-0000-0000-0000-000000000040', 'It is distinguished from SIADH by the opposite sodium and urine concentration pattern: DI causes hypernatraemia with dilute urine, while SIADH causes hyponatraemia with concentrated urine.', 2),
('c5000000-0000-0000-0000-000000000040', 'Management includes careful fluid balance monitoring and desmopressin (a synthetic ADH analogue) replacement once confirmed, with close sodium monitoring to avoid overcorrection.', 3),
('c5000000-0000-0000-0000-000000000041', 'Bitemporal hemianopia is the classic visual field defect from optic chiasm compression by a suprasellar mass, most commonly a pituitary macroadenoma.', 1),
('c5000000-0000-0000-0000-000000000041', 'Non-functioning pituitary adenomas present with mass effect (visual field loss, headache) and/or hypopituitarism (from compression of normal pituitary tissue), rather than a hormone excess syndrome.', 2),
('c5000000-0000-0000-0000-000000000041', 'All patients with a pituitary macroadenoma require formal visual field assessment and full anterior pituitary hormone profiling to assess for both mass effect and any hormonal excess or deficiency.', 3),
('c5000000-0000-0000-0000-000000000042', 'Hyperprolactinaemia suppresses gonadotrophin-releasing hormone (GnRH) pulsatility, leading to secondary hypogonadism, which can present as reduced libido, erectile dysfunction, and gynaecomastia in men.', 1),
('c5000000-0000-0000-0000-000000000042', 'Dopamine agonists are first-line treatment for both micro- and macroprolactinomas, in contrast to most other pituitary adenoma subtypes which are primarily managed surgically.', 2),
('c5000000-0000-0000-0000-000000000042', 'Other causes of hyperprolactinaemia (certain medications, hypothyroidism, renal failure, stress) should be excluded, though normal TSH/T4 here makes hypothyroidism unlikely.', 3),
('c5000000-0000-0000-0000-000000000043', 'Primary hypothyroidism is characterised by a raised TSH with a low free T4, reflecting failure at the level of the thyroid gland itself with an appropriate compensatory pituitary response.', 1),
('c5000000-0000-0000-0000-000000000043', 'Levothyroxine is first-line treatment, with dose titration guided by TSH (aiming for the level to normalise) rather than solely by symptoms.', 2),
('c5000000-0000-0000-0000-000000000043', $x$The most common cause of primary hypothyroidism in iodine-replete areas is autoimmune (Hashimoto's) thyroiditis.$x$, 3),
('c5000000-0000-0000-0000-000000000044', $x$Graves' disease is caused by TSH-receptor stimulating autoantibodies and classically presents with a diffuse, vascular goitre (may have an audible bruit) and specific extrathyroidal features: thyroid eye disease (exophthalmos, lid retraction) and, less commonly, pretibial myxoedema.$x$, 1),
('c5000000-0000-0000-0000-000000000044', 'Biochemically, primary hyperthyroidism shows suppressed TSH with raised free T4/T3.', 2),
('c5000000-0000-0000-0000-000000000044', 'First-line treatment options include antithyroid drugs (e.g. carbimazole), radioactive iodine, or surgery, chosen based on patient factors and preference.', 3),
('c5000000-0000-0000-0000-000000000045', 'Thyroid storm is a life-threatening exacerbation of hyperthyroidism, typically precipitated by infection, surgery, trauma, or non-adherence to antithyroid medication, presenting with hyperpyrexia, tachyarrhythmia, agitation/confusion, and multi-organ dysfunction (e.g. jaundice, cardiac failure).', 1),
('c5000000-0000-0000-0000-000000000045', 'Management combines supportive care (fluids, cooling), antithyroid drugs, beta-blockade for adrenergic symptoms, and corticosteroids (which reduce T4-to-T3 conversion and cover possible relative adrenal insufficiency), usually in a high-dependency/intensive care setting.', 2),
('c5000000-0000-0000-0000-000000000045', 'Identifying and treating the precipitant (e.g. infection) is essential alongside specific thyroid storm treatment.', 3),
('c5000000-0000-0000-0000-000000000046', 'Myxoedema coma is a rare, life-threatening decompensation of severe untreated hypothyroidism, presenting with hypothermia, bradycardia, reduced consciousness, and multi-organ dysfunction; it carries a high mortality without prompt treatment.', 1),
('c5000000-0000-0000-0000-000000000046', 'Treatment requires urgent IV thyroid hormone replacement combined with IV hydrocortisone (to avoid precipitating adrenal crisis, as coexisting adrenal insufficiency may be present or unmasked), gradual rewarming, and intensive monitoring.', 2),
('c5000000-0000-0000-0000-000000000046', 'Common precipitants include infection, cold exposure, sedative drugs, and cessation of thyroid hormone replacement, particularly in elderly patients.', 3),
('c5000000-0000-0000-0000-000000000047', 'TSH reference ranges are lower in pregnancy (particularly in the first trimester) than in the general population, and even subclinical hypothyroidism is usually treated with levothyroxine during pregnancy.', 1),
('c5000000-0000-0000-0000-000000000047', 'Adequate maternal thyroid hormone, especially in early pregnancy, is important for fetal neurodevelopment before the fetal thyroid gland becomes fully functional.', 2),
('c5000000-0000-0000-0000-000000000047', 'Thyroid function and levothyroxine dose requirements should be monitored throughout pregnancy, as requirements typically increase as pregnancy progresses.', 3),
('c5000000-0000-0000-0000-000000000048', 'Papillary thyroid carcinoma is the most common thyroid cancer subtype and generally carries a good prognosis, particularly in younger patients without extrathyroidal spread.', 1),
('c5000000-0000-0000-0000-000000000048', 'Standard management is surgical resection (thyroidectomy), often followed by radioactive iodine ablation of remnant tissue and lifelong levothyroxine with TSH suppression to reduce recurrence risk.', 2),
('c5000000-0000-0000-0000-000000000048', 'Suspicious features on ultrasound (irregular margins, microcalcifications, increased vascularity) guide the decision for fine needle aspiration cytology of a thyroid nodule.', 3),
('c5000000-0000-0000-0000-000000000049', 'Amiodarone is iodine-rich and can cause both hypothyroidism and thyrotoxicosis; thyroid function should be checked before starting amiodarone and monitored periodically during treatment.', 1),
('c5000000-0000-0000-0000-000000000049', 'Amiodarone-induced thyrotoxicosis can result from an iodine-induced Jod-Basedow effect (type 1, often in patients with underlying nodular thyroid disease) or a destructive thyroiditis (type 2), which has implications for management (e.g. antithyroid drugs versus corticosteroids).', 2),
('c5000000-0000-0000-0000-000000000049', $x$Whether amiodarone needs to be stopped depends on the type of thyroid dysfunction and the necessity of amiodarone for the patient's arrhythmia; this decision often requires specialist endocrine input.$x$, 3),
('c5000000-0000-0000-0000-000000000050', 'Postpartum thyroiditis classically has a biphasic course: a transient thyrotoxic phase (due to release of stored thyroid hormone from gland inflammation) followed by a hypothyroid phase, with eventual return to euthyroidism in most women.', 1),
('c5000000-0000-0000-0000-000000000050', $x$The thyroid gland is typically mildly enlarged and non-tender, distinguishing it from subacute (de Quervain's) thyroiditis, which is painful/tender.$x$, 2),
('c5000000-0000-0000-0000-000000000050', 'Some women with postpartum thyroiditis go on to develop permanent hypothyroidism and require long-term follow-up of thyroid function.', 3);
